using System.IO.Compression;

namespace Erlang;

internal static class BeamLiteralReader
{
    public static IReadOnlyList<Term> Read(ReadOnlyMemory<byte> payload, EtfDecodeOptions? decoding = null)
    {
        var header = new BeamCursor(payload);
        int capacity = header.ReadInt32();
        if (capacity < 0 || capacity > BeamLiteralLimits.MaximumDecodedTableBytes)
            throw new InvalidDataException(BeamLiteralDiagnostics.InvalidCapacity);
        ReadOnlyMemory<byte> data = header.Read(header.Remaining);
        if (capacity != BeamLiteralWire.UncompressedTableMarker)
            data = Decompress(data, capacity);
        if (data.Length > BeamLiteralLimits.MaximumDecodedTableBytes)
            throw new InvalidDataException(BeamLiteralDiagnostics.InvalidCapacity);
        var cursor = new BeamCursor(data);
        int count = cursor.ReadInt32();
        if (count < 0 || (long)count * BeamLiteralWire.LiteralEntryBytes >= BeamWire.TableAllocationSanityBytes
            || count > cursor.Remaining / BeamLiteralWire.EntrySizeFieldBytes)
            throw new InvalidDataException(BeamLiteralDiagnostics.InvalidCount);
        var literals = new List<Term>(count);
        for (int index = 0; index < count; index++)
        {
            ReadOnlyMemory<byte> external = cursor.Read(cursor.ReadInt32());
            if (external.Length > BeamLiteralWire.ExternalTermTagOffset && external.Span[BeamLiteralWire.ExternalTermTagOffset] == BeamLiteralWire.CompressedExternalTermTag)
                throw new InvalidDataException(BeamLiteralDiagnostics.InvalidExternalTerm);
            try
            {
                literals.Add(ExternalTermFormat.DecodeOne(external.Span, decoding ?? new EtfDecodeOptions(), BeamLiteralLimits.MaximumDecodedTableBytes).Term);
            }
            catch (ErlangException exception)
            {
                throw new InvalidDataException(BeamLiteralDiagnostics.InvalidExternalTerm, exception);
            }
        }

        return literals.AsReadOnly();
    }

    private static ReadOnlyMemory<byte> Decompress(ReadOnlyMemory<byte> compressed, int capacity)
    {
        try
        {
            int memberBytes = BeamZlibMemberBoundary.Measure(compressed.Span, capacity);
            using var input = new MemoryStream(compressed[..memberBytes].ToArray(), false);
            using var zlib = new ZLibStream(input, CompressionMode.Decompress);
            using var output = new MemoryStream();
            byte[] buffer = new byte[BeamLiteralLimits.DecompressionBufferBytes];
            int read;
            while ((read = zlib.Read(buffer)) != 0)
            {
                if (output.Length + read > capacity)
                    throw new InvalidDataException(BeamLiteralDiagnostics.InvalidCapacity);
                output.Write(buffer, 0, read);
            }

            return output.ToArray();
        }
        catch (InvalidDataException exception)
        {
            throw new InvalidDataException(BeamLiteralDiagnostics.InvalidCompressedTable, exception);
        }
    }
}

namespace Erlang;

internal static class BeamLoaderApi
{
    internal static Term Prepare(ProcessContext context, Term module, Term bytes)
    {
        Term code = Decompress(bytes);
        try
        {
            return PrepareImage(context, module, code);
        }
        catch (ErlangException exception) when (exception.ExceptionClass == ErlangExceptionClasses.Error)
        {
            throw WithErrorInfo(
                context,
                exception,
                BeamLoaderNames.Prepare,
                [module, code]
            );
        }
    }

    private static Term Decompress(Term bytes)
    {
        if (bytes is BitString { IsBinary: true } binary && binary.ToArray().AsSpan().StartsWith(BeamIffWire.FormId))
            return bytes;
        try
        {
            byte[] input = ErlangIoData.Flatten(bytes, false, false).ToArray();

            return new BitString(BeamGzipMembers.Inflate(input));
        }
        catch (Exception exception) when (exception is ErlangException or InvalidDataException or IOException or OverflowException or ArgumentException)
        {
            return bytes;
        }
    }

    private static Term PrepareImage(ProcessContext context, Term module, Term bytes)
    {
        if (module is not Atom name || bytes is not BitString { IsBinary: true } binary)
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        byte[] input = binary.ToArray();
        try
        {
            BeamStructure structure = BeamStructureReader.Read(input, context.Runtime.Modules.PreparationDecodeOptions());
            if (structure.Atoms[1] != name.Name)
                return Error(BeamLoaderNames.BadFile);
            PreparedBeamImage image = context.Runtime.Modules.PrepareBeam(input);

            return context.Runtime.ReferenceResources.CreatePrepared(image);
        }
        catch (InvalidDataException)
        {
            return Error(BeamLoaderNames.BadFile);
        }
    }

    internal static Term HasOnLoad(ProcessContext context, Term reference)
    {
        if (reference is not ReferenceTerm identity)
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        if (!context.Runtime.ReferenceResources.TryReadPreparedMetadata(identity, out PreparedBeamImage? image))
            throw new ErlangException(ErlangErrorReasons.BadArgument);

        return Term.A(image!.HasOnLoad ? ErlangBooleanAtoms.True : ErlangBooleanAtoms.False);
    }

    internal static Term Finish(ProcessContext context, Term list)
    {
        Term[] references = Cons.Items(list).ToArray();
        var identities = new List<ReferenceTerm>();
        foreach (Term term in references)
        {
            if (term is not ReferenceTerm identity)
                throw new ErlangException(ErlangErrorReasons.BadArgument);
            identities.Add(identity);
        }

        return context.Runtime.ReferenceResources.FinishPreparedReferences(identities);
    }

    internal static Term LoadModule(ProcessContext context, Term module, Term bytes)
    {
        try
        {
            return LoadImage(context, module, bytes);
        }
        catch (ErlangException exception) when (exception.ExceptionClass == ErlangExceptionClasses.Error)
        {
            throw WithErrorInfo(
                context,
                exception,
                BeamLoaderNames.LoadModule,
                [module, bytes]
            );
        }
    }

    private static Term LoadImage(ProcessContext context, Term module, Term bytes)
    {
        Term prepared = Prepare(context, module, bytes);
        if (prepared is not ReferenceTerm)
            return prepared;
        Term result = Finish(context, Cons.From([prepared]));
        if (result is Atom { Name: BeamLoaderNames.Ok })
            return Term.Tuple(Term.A(BeamLoaderNames.Module), module);
        if (result is TupleTerm failure)
            return Term.Tuple(Term.A(BeamLoaderNames.Error), failure.Items[0]);

        throw new InvalidOperationException(BeamLoaderDiagnostics.UnexpectedLoadingResult);
    }

    internal static Term DynamicCallOnLoad(ProcessContext context, Term module)
        => throw new ErlangException(ErlangErrorReasons.BadArgument);

    internal static Term FinishOnLoad(ProcessContext context, Term module, Term keep)
    {
        bool retain = CoreModules.Bool(keep);
        if (module is not Atom name)
            throw new ErlangException(ErlangErrorReasons.BadArgument);

        return context.Runtime.Modules.FinishLoaderOnLoad(name.Name, retain);
    }

    private static ErlangException WithErrorInfo(
        ProcessContext context,
        ErlangException exception,
        string function,
        IReadOnlyList<Term> arguments
    )
    {
        var info = new MapTerm([
            new KeyValuePair<Term, Term>(Term.A(BeamLoaderNames.ErrorInfoModule), Term.A(BeamLoaderNames.ErrorFormatter))
        ]);

        return new ErlangException(exception.Reason, exception.ExceptionClass)
        {
            ExplicitStackTrace = true,
            StackTraceTerm = context.CaptureErrorStack(Cons.From(arguments), info, function)
        };
    }

    private static Term Error(string reason)
        => Term.Tuple(Term.A(BeamLoaderNames.Error), Term.A(reason));

}

using System.Security.Cryptography;

namespace Erlang;

public sealed class BeamModule
{
    private readonly BeamLinkedCode code;

    private BeamModule(BeamLinkedCode code, string inputSha256)
    {
        this.code = code;
        InputSha256 = inputSha256;
        Name = code.Structure.Atoms[1]!;
        Exports = Array.AsReadOnly(code.Exports.Select(value => new BeamFunctionSignature(value.Name, value.Arity)).ToArray());
        Functions = Array.AsReadOnly(code.Functions.Select(value => new BeamFunctionSignature(value.Name, value.Arity)).ToArray());
    }

    public string Name { get; }
    public string InputSha256 { get; }
    public IReadOnlyList<BeamFunctionSignature> Exports { get; }
    public IReadOnlyList<BeamFunctionSignature> Functions { get; }
    public bool HasOnLoad => code.OnLoadEntryLabel is not null;

    public static BeamModule Prepare(ReadOnlyMemory<byte> bytes)
    {
        byte[] owned = bytes.ToArray();
        BeamLinkedCode linked = BeamLinkedCodeReader.Read(BeamStructureReader.Read(owned));

        return new(linked, Convert.ToHexString(SHA256.HashData(owned)));
    }

    public bool Supports(string function, int arity)
    {
        if (HasOnLoad)
            return false;
        BeamLinkedFunction? entry = code.Exports.SingleOrDefault(value => value.Name == function && value.Arity == arity);
        if (entry is null)
        {
            return false;
        }
        try
        {
            BeamRegisterValidation.Validate(code, entry);

            return true;
        }
        catch (NotSupportedException)
        {
            return false;
        }
    }

    public ValueTask<Term> Invoke(ProcessContext context, string function, params Term[] arguments)
    {
        ArgumentNullException.ThrowIfNull(context);
        ArgumentNullException.ThrowIfNull(function);
        ArgumentNullException.ThrowIfNull(arguments);
        context.Cancellation.ThrowIfCancellationRequested();
        foreach (Term literal in code.Structure.Literals)
            context.Runtime.ObserveIncomingTerm(literal);
        foreach (Term argument in arguments)
            context.Runtime.ObserveIncomingTerm(argument);
        if (HasOnLoad)
        {
            if (!code.Exports.Any(entry => entry.Name == function && entry.Arity == arguments.Length))
                throw new InvalidDataException(BeamModuleDiagnostics.MissingExport);
            throw new NotSupportedException(BeamRegisterNames.Unsupported);
        }

        return BeamRegisterInterpreter.Execute(
            context,
            code,
            function,
            Array.AsReadOnly(arguments.ToArray())
        );
    }
}

namespace Erlang;

internal static class BeamPublicationMetadata
{
    internal static BeamPreparedMetadata Read(BeamLinkedCode code, EtfDecodeOptions? decoding = null)
    {
        if (code.Structure.Chunks.Any(chunk => chunk.Id == BeamPreparationNames.RecordsChunk && chunk.Payload.Length != 0))
            throw new NotSupportedException(BeamPreparationNames.UnsupportedRecords);
        if (code.Structure.Chunks.Any(chunk => chunk.Id == BeamLambdaWire.Chunk && chunk.Payload.Length != 0))
            throw new NotSupportedException(BeamPreparationNames.UnsupportedLambdas);
        BeamDecodedMetadata attributes = ReadTerm(code, BeamPreparationNames.AttributesChunk, decoding);
        BeamDecodedMetadata compilation = ReadTerm(code, BeamPreparationNames.CompilationChunk, decoding);
        var descriptor = new ModuleCodeDescriptor(
            code.Functions.Select(value => (value.Name, value.Arity)),
            code.Exports.Select(value => (value.Name, value.Arity)),
            BeamChecksumReader.Read(code),
            compilation.Value,
            attributes.Value,
            attributePolicy: ModuleAttributePolicy.PreserveDecoded
        );

        return new(descriptor, attributes.Provenance, compilation.Provenance);
    }

    private static BeamDecodedMetadata ReadTerm(BeamLinkedCode code, string id, EtfDecodeOptions? decoding)
    {
        BeamChunk? chunk = code.Structure.Chunks.LastOrDefault(value => value.Id == id);
        if (chunk is null || chunk.Payload.Length == 0)
            return new(Nil.Value, new(chunk is not null, 0, 0));
        if (chunk.Payload.Length > BeamMetadataWire.ExternalTermTagOffset
            && chunk.Payload.Span[BeamMetadataWire.ExternalTermTagOffset] == BeamMetadataWire.CompressedExternalTermTag)
            throw new InvalidDataException(BeamPreparationNames.InvalidMetadata);
        try
        {
            EtfDecodedTerm decoded = ExternalTermFormat.DecodeOne(chunk.Payload.Span, decoding ?? new EtfDecodeOptions());

            return new(decoded.Term, new(true, chunk.Payload.Length, decoded.Used));
        }
        catch (ErlangException exception)
        {
            throw new InvalidDataException(BeamPreparationNames.InvalidMetadata, exception);
        }
    }
}

using System.Buffers;
using System.Text;

namespace Erlang;

internal static class BeamStructureReader
{
    public static BeamStructure Read(ReadOnlyMemory<byte> input, EtfDecodeOptions? decoding = null)
    {
        byte[] owned = input.ToArray();
        var outer = new BeamCursor(owned);
        if (!outer.Read(BeamIffWire.IdentifierBytes).Span.SequenceEqual(BeamIffWire.FormId))
        {
            throw new InvalidDataException(BeamDiagnostics.FormId);
        }
        var form = new BeamCursor(outer.Read(outer.ReadInt32()));
        if (!form.Read(BeamIffWire.IdentifierBytes).Span.SequenceEqual(BeamIffWire.FormType))
        {
            throw new InvalidDataException(BeamDiagnostics.FormType);
        }
        var chunks = new List<BeamChunk>();
        var selected = new Dictionary<string, BeamChunk>(StringComparer.Ordinal);
        while (form.Remaining != 0)
        {
            int offset = form.Position + BeamIffWire.FormHeaderBytes;
            string id = Encoding.ASCII.GetString(form.Read(BeamIffWire.IdentifierBytes).Span);
            int length = form.ReadInt32();
            if (length < 0 || length > BeamClrLimits.MaximumInputBytes - BeamIffWire.ChunkAlignmentMask)
            {
                throw new InvalidDataException(BeamDiagnostics.ChunkSize);
            }
            int padding = ((length + BeamIffWire.ChunkAlignmentMask) & ~BeamIffWire.ChunkAlignmentMask) - length;
            var chunk = new BeamChunk(
                id,
                offset,
                form.Read(length),
                padding
            );
            form.Read(padding);
            chunks.Add(chunk);
            selected[id] = chunk;
        }
        BeamCodeHeader code = ReadCode(Required(selected, BeamWire.CodeChunk));
        if (!selected.TryGetValue(BeamWire.AtomsChunk, out BeamChunk? atomsChunk) || atomsChunk.Payload.Length == 0)
        {
            throw new InvalidDataException(selected.TryGetValue(BeamWire.ObsoleteAtomsChunk, out BeamChunk? obsolete)
                && obsolete.Payload.Length != 0 ? BeamDiagnostics.ObsoleteAtoms : BeamDiagnostics.MissingAtoms);
        }
        IReadOnlyList<string?> atoms = ReadAtoms(atomsChunk.Payload);
        IReadOnlyList<BeamImport> imports = ReadImports(Required(selected, BeamWire.ImportsChunk), atoms.Count);
        IReadOnlyList<BeamExport> exports = ReadExports(Required(selected, BeamWire.ExportsChunk), atoms.Count);

        IReadOnlyList<Term> literals = selected.TryGetValue(BeamLiteralWire.Chunk, out BeamChunk? literalChunk) && literalChunk.Payload.Length != 0
            ? BeamLiteralReader.Read(literalChunk.Payload, decoding)
            : Array.Empty<Term>();

        return new(
            chunks.AsReadOnly(),
            atoms,
            imports,
            exports,
            code,
            literals,
            outer.Remaining
        );
    }

    private static ReadOnlyMemory<byte> Required(Dictionary<string, BeamChunk> chunks, string id)
    {
        if (!chunks.TryGetValue(id, out BeamChunk? chunk) || chunk.Payload.Length == 0)
        {
            throw new InvalidDataException(BeamDiagnostics.MissingChunk(id));
        }

        return chunk.Payload;
    }

    private static BeamCodeHeader ReadCode(ReadOnlyMemory<byte> payload)
    {
        var cursor = new BeamCursor(payload);
        int size = cursor.ReadInt32();
        var header = new BeamCursor(cursor.Read(size));
        int version = header.ReadInt32();
        if (version != BeamWire.FormatVersion)
        {
            throw new InvalidDataException(BeamDiagnostics.FormatVersion);
        }
        int opcode = header.ReadInt32();
        int labels = header.ReadInt32();
        int functions = header.ReadInt32();

        return new(
            version,
            opcode,
            labels,
            functions,
            cursor.Read(cursor.Remaining)
        );
    }

    private static IReadOnlyList<string?> ReadAtoms(ReadOnlyMemory<byte> payload)
    {
        var cursor = new BeamCursor(payload);
        int rawCount = cursor.ReadInt32();
        bool longLengths = rawCount < 0;
        if (rawCount == int.MinValue)
        {
            throw new InvalidDataException(BeamDiagnostics.AtomCount);
        }
        int count = Math.Abs(rawCount);
        CheckCount(count, 1, BeamWire.AtomEntryBytes);
        var atoms = new List<string?> { null };
        for (int index = 0; index < count; index++)
        {
            int length;
            if (longLengths)
            {
                BeamCompactValue value = BeamCompactReader.Read(cursor);
                if (!value.FitsNativeWord)
                {
                    throw new InvalidDataException(BeamDiagnostics.LongAtomLength);
                }
                ulong nativeLength = unchecked((ulong)(long)value.Value);
                if (nativeLength > BeamClrLimits.MaximumInputBytes)
                {
                    throw new InvalidDataException(BeamDiagnostics.AtomLengthBounds);
                }
                length = (int)nativeLength;
            }
            else
            {
                length = cursor.ReadByte();
            }
            ReadOnlySpan<byte> utf8 = cursor.Read(length).Span;
            var text = new StringBuilder();
            int characters = 0;
            while (!utf8.IsEmpty && characters < BeamWire.MaximumAtomCharacters)
            {
                if (Rune.DecodeFromUtf8(utf8, out Rune rune, out int consumed) != OperationStatus.Done)
                {
                    throw new InvalidDataException(BeamDiagnostics.Utf8Atom);
                }
                text.Append(rune.ToString());
                utf8 = utf8[consumed..];
                characters++;
            }
            atoms.Add(text.ToString());
        }

        return atoms.AsReadOnly();
    }

    private static IReadOnlyList<BeamImport> ReadImports(ReadOnlyMemory<byte> payload, int atoms)
    {
        var cursor = new BeamCursor(payload);
        int count = cursor.ReadInt32();
        CheckCount(count, 0, BeamWire.ImportEntryBytes);
        var entries = new List<BeamImport>();
        for (int index = 0; index < count; index++)
        {
            int module = cursor.ReadInt32();
            int function = cursor.ReadInt32();
            int arity = cursor.ReadInt32();
            CheckAtom(module, atoms);
            CheckAtom(function, atoms);
            CheckArity(arity);
            entries.Add(new(module, function, arity));
        }

        return entries.AsReadOnly();
    }

    private static IReadOnlyList<BeamExport> ReadExports(ReadOnlyMemory<byte> payload, int atoms)
    {
        var cursor = new BeamCursor(payload);
        int count = cursor.ReadInt32();
        CheckCount(count, 0, BeamWire.ExportEntryBytes);
        var entries = new List<BeamExport>();
        for (int index = 0; index < count; index++)
        {
            int function = cursor.ReadInt32();
            int arity = cursor.ReadInt32();
            int label = cursor.ReadInt32();
            CheckAtom(function, atoms);
            CheckArity(arity);
            if (label < 0)
            {
                throw new InvalidDataException(BeamDiagnostics.ExportLabel);
            }
            entries.Add(new(function, arity, label));
        }

        return entries.AsReadOnly();
    }

    private static void CheckCount(int count, int minimum, int entryBytes)
    {
        if (count < minimum || count >= BeamWire.TableAllocationSanityBytes / entryBytes)
        {
            throw new InvalidDataException(BeamDiagnostics.TableCount);
        }
    }

    private static void CheckAtom(int index, int count)
    {
        if (index < 0 || index >= count)
        {
            throw new InvalidDataException(BeamDiagnostics.AtomIndex);
        }
    }

    private static void CheckArity(int arity)
    {
        if (arity < 0 || arity > BeamWire.MaximumArity)
        {
            throw new InvalidDataException(BeamDiagnostics.FunctionArity);
        }
    }
}

using System.Numerics;

namespace Erlang;

public static class CoreModules
{
    public static void Register(ModuleRegistry r)
    {
        r.InstallPreloaded(RegisterCode);
    }

    private static void RegisterCode(ModuleRegistry r)
    {
        void Add(
            string module,
            string name,
            int arity,
            Func<ProcessContext, IReadOnlyList<Term>, Term> f
        ) => r.Register(
            module,
            name,
            arity,
            (c, a) => ValueTask.FromResult(f(c, a))
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Self,
            0,
            (c, a) => c.Self
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Length,
            1,
            (c, a) => Term.I(Cons.Items(a[0]).LongCount())
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Head,
            1,
            (c, a) => a[0] is Cons l ? l.Head : throw new ErlangException(ErlangErrorReasons.BadArgument)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Tail,
            1,
            (c, a) => a[0] is Cons l ? l.Tail : throw new ErlangException(ErlangErrorReasons.BadArgument)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Element,
            2,
            (c, a) => a[0] is Integer i && a[1] is TupleTerm t && i.Value > 0 && i.Value <= t.Items.Count ? t.Items[(int)i.Value - 1] : throw new ErlangException(ErlangErrorReasons.BadArgument)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.TupleSize,
            1,
            (c, a) => a[0] is TupleTerm t ? Term.I(t.Items.Count) : throw new ErlangException(ErlangErrorReasons.BadArgument)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsAtom,
            1,
            (c, a) => Boolean(a[0] is Atom)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsInteger,
            1,
            (c, a) => Boolean(a[0] is Integer)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsFloat,
            1,
            (c, a) => Boolean(a[0] is FloatTerm)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsNumber,
            1,
            (c, a) => Boolean(a[0] is Integer or FloatTerm)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsTuple,
            1,
            (c, a) => Boolean(a[0] is TupleTerm)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsBinary,
            1,
            (c, a) => Boolean(a[0] is BitString b && b.IsBinary)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsBitString,
            1,
            (c, a) => Boolean(a[0] is BitString)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.BitSize,
            1,
            (c, a) => a[0] is BitString b ? Term.I(b.BitLength) : throw new ErlangException(ErlangErrorReasons.BadArgument)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.ByteSize,
            1,
            (c, a) => a[0] is BitString b ? Term.I((b.BitLength + 7L) / 8) : throw new ErlangException(ErlangErrorReasons.BadArgument)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsList,
            1,
            (c, a) => Boolean(a[0] is Cons or Nil)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsPid,
            1,
            (c, a) => Boolean(a[0] is Pid)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsMap,
            1,
            (c, a) => Boolean(a[0] is MapTerm)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.MapSize,
            1,
            (c, a) => a[0] is MapTerm m ? Term.I(m.Entries.Count) : throw new ErlangException(Term.Tuple(Term.A(ErlangErrorReasons.BadMap), a[0]))
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.MapGet,
            2,
            (c, a) => a[1] is MapTerm m ? m.Get(a[0]) : throw new ErlangException(Term.Tuple(Term.A(ErlangErrorReasons.BadMap), a[1]))
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsMapKey,
            2,
            (c, a) => a[1] is MapTerm m ? Boolean(m.TryGet(a[0], out _)) : throw new ErlangException(Term.Tuple(Term.A(ErlangErrorReasons.BadMap), a[1]))
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.MakeReference,
            0,
            (c, a) => c.Runtime.MakeReference()
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Register,
            2,
            (c, a) =>
 {
     if (a[1] is PortTerm port)
         c.Runtime.RegisterPort(AtomName(a[0]), port);
     else
         c.Runtime.Register(AtomName(a[0]), PidValue(a[1]));

     return Term.A(ErlangBooleanAtoms.True);
 }
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.WhereIs,
            1,
            (c, a) => c.Runtime.WhereIs(AtomName(a[0]))
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Unregister,
            1,
            (c, a) =>
 {
     c.Runtime.Unregister(AtomName(a[0]));

     return Term.A(ErlangBooleanAtoms.True);
 }
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Link,
            1,
            (c, a) =>
 {
     if (a[0] is PortTerm port)
         c.Runtime.Ports.Link(c, port);
     else
         c.Runtime.Link(c, PidValue(a[0]));

     return Term.A(ErlangBooleanAtoms.True);
 }
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.Unlink,
            1,
            (c, a) =>
 {
     if (a[0] is PortTerm port)
         c.Runtime.Ports.Unlink(c, port);
