namespace Erlang;

internal static class ErlangEtfRegistrations
{
    public static void Register(ModuleRegistry registry)
    {
        foreach (string name in new[] { ErlangEtfNames.Encode, ErlangEtfNames.IoVec, ErlangEtfNames.Size, ErlangEtfNames.Decode })
            foreach (int arity in new[] { 1, 2 })
                registry.Register(
                    ErlangModuleNames.Module,
                    name,
                    arity,
                    (context, arguments) => ValueTask.FromResult(Invoke(context, name, arguments))
                );
    }

    private static Term Invoke(ProcessContext context, string name, IReadOnlyList<Term> arguments)
    {
        Term options = arguments.Count == 2 ? arguments[1] : Nil.Value;
        if (name == ErlangEtfNames.Decode)
            return Decode(context, arguments[0], options);
        var encoding = Encoding(context, options);

        return name switch
        {
            ErlangEtfNames.Encode => BitString.FromOwnedBytes(ExternalTermFormat.Encode(arguments[0], encoding)),
            ErlangEtfNames.IoVec => encoding.CompressionLevel == ErlangEtfParameters.Uncompressed ? Cons.From(ExternalTermFormat.EncodeIoVec(arguments[0], encoding)) : BitString.FromOwnedBytes(ExternalTermFormat.Encode(arguments[0], encoding)),
            ErlangEtfNames.Size => Term.I(ExternalTermFormat.EncodedSize(arguments[0], encoding)),
            _ => throw new InvalidOperationException()
        };
    }

    private static EtfEncodingOptions Encoding(ProcessContext context, Term options)
    {
        var wire = context.Runtime.LocalIdentity.Snapshot;
        var result = new EtfEncodingOptions
        {
            LocalNode = wire.Node,
            LocalCreation = wire.Creation,
            NodeIdentity = context.Runtime.LocalIdentity,
            NodeSnapshot = wire,
            LocalSeed = context.Runtime.LocalTermSeed,
            FunctionOwner = context.Runtime.InitializationPid
        };
        foreach (Term value in Cons.Items(options))
        {
            if (value is Atom atom)
            {
                result = atom.Name switch
                {
                    ErlangEtfNames.Compressed => result with { CompressionLevel = ErlangEtfParameters.DefaultCompression },
                    ErlangEtfNames.Deterministic => result with { Deterministic = true },
                    ErlangEtfNames.Local => result with { Local = true },
                    _ => throw new ErlangException(ErlangErrorReasons.BadArgument)
                };
            }
            else if (value is TupleTerm { Items.Count: 2 } tuple && tuple.Items[0] is Atom key && tuple.Items[1] is Integer integer)
            {
                if (key.Name == ErlangEtfNames.Compressed && integer.Value >= ErlangEtfParameters.MinimumCompression && integer.Value <= ErlangEtfParameters.MaximumCompression)
                    result = result with { CompressionLevel = (int)integer.Value };
                else if (key.Name == ErlangEtfNames.MinorVersion && integer.Value >= ErlangEtfParameters.MinimumMinorVersion && integer.Value <= ErlangEtfParameters.MaximumMinorVersion)
                    result = result with { MinorVersion = (int)integer.Value };
                else
                    throw new ErlangException(ErlangErrorReasons.BadArgument);
            }
            else
                throw new ErlangException(ErlangErrorReasons.BadArgument);
        }

        return result;
    }

    private static Term Decode(ProcessContext context, Term value, Term options)
    {
        bool safe = false, used = false;
        foreach (Term option in Cons.Items(options))
        {
            if (option is Atom { Name: ErlangEtfNames.Safe })
                safe = true;
            else if (option is Atom { Name: ErlangEtfNames.Used })
                used = true;
            else
                throw new ErlangException(ErlangErrorReasons.BadArgument);
        }
        if (value is not BitString { IsBinary: true } binary)
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        EtfDecodedTerm result = context.Runtime.ImportExternalTerm(binary.ByteSpan, new EtfDecodeOptions { Safe = safe });

        return used ? Term.Tuple(result.Term, Term.I(result.Used)) : result.Term;
    }
}

namespace Erlang;

internal static class ErlangProcessQueryRegistrations
{
    public static void Register(ModuleRegistry registry)
    {
        void Add(string name, int arity, ErlangFunction body) => registry.Register(
            ErlangModuleNames.Module,
            name,
            arity,
            body
        );
        Add(ErlangProcessQueryNames.Node, 0, (context, _) => ValueTask.FromResult<Term>(context.Runtime.NodeAtom));
        Add(
            ErlangProcessQueryNames.Node,
            1,
            (_, arguments) => ValueTask.FromResult<Term>(Term.A(arguments[0] switch
            {
                Pid pid => pid.Node,
                PortTerm port => port.Node,
                ReferenceTerm reference => reference.Node,
                _ => throw new ErlangException(ErlangErrorReasons.BadArgument)
            }))
        );
        Add(ErlangProcessQueryNames.Processes, 0, (context, _) => ValueTask.FromResult(Cons.From(context.Runtime.ProcessSnapshot())));
        Add(
            ErlangProcessQueryNames.Registered,
            0,
            (context, _) => ValueTask.FromResult(Cons.From(context.Runtime.RegisteredSnapshot().Select(Term.A)))
        );
        Add(
            ErlangProcessQueryNames.Alive,
            1,
            (context, arguments) =>
        {
            if (arguments[0] is not Pid pid || pid.Node != context.Runtime.Node)
                throw new ErlangException(ErlangErrorReasons.BadArgument);

            return ValueTask.FromResult<Term>(Term.A(context.Runtime.IsAlive(pid) ? ErlangBooleanAtoms.True : ErlangBooleanAtoms.False));
        }
        );
        Add(
            ErlangProcessQueryNames.Yield,
            0,
            async (context, _) =>
        {
            context.Cancellation.ThrowIfCancellationRequested();
            context.Runtime.AdmitSignals(context);
            await Task.Yield();
            context.Cancellation.ThrowIfCancellationRequested();

            return Term.A(ErlangBooleanAtoms.True);
        }
        );
        Add(
            ErlangProcessQueryNames.Bump,
            1,
            async (context, arguments) =>
        {
            if (arguments[0] is not Integer value || value.Value < 0 || value.Value > ProcessSchedulingLimits.MaximumSmallBump)
                throw new ErlangException(ErlangErrorReasons.BadArgument);
            await context.BumpReductionsAsync((int)System.Numerics.BigInteger.Min(value.Value, ProcessSchedulingLimits.NativeMaximumBump));

            return Term.A(ErlangBooleanAtoms.True);
        }
        );
    }
}

namespace Erlang;

public sealed class HostDistribution : IDisposable
{
    private readonly object gate = new();
    private readonly ProcessRuntime runtime;
    private readonly long maximumQueuedPayloadBytes;
    private readonly int maximumQueuedBuffers;
    private readonly int maximumQueuedSegments;
    private readonly Dictionary<string, HostDistributionEntry> entries = new(StringComparer.Ordinal);
    private readonly Dictionary<Pid, HostDistributionEntry> controllers = new();
    private ulong generation;
    private bool closed;

    public HostDistribution(
        ProcessRuntime runtime,
        long maximumQueuedPayloadBytes,
        int maximumQueuedBuffers,
        int maximumQueuedSegments
    )
    {
        ArgumentNullException.ThrowIfNull(runtime);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(maximumQueuedPayloadBytes);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(maximumQueuedBuffers);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(maximumQueuedSegments);
        this.runtime = runtime;
        this.maximumQueuedPayloadBytes = maximumQueuedPayloadBytes;
        this.maximumQueuedBuffers = maximumQueuedBuffers;
        this.maximumQueuedSegments = maximumQueuedSegments;
    }

    public HostDistributionHandle Attach(string channel, ProcessContext controller)
    {
        ArgumentException.ThrowIfNullOrEmpty(channel);
        ArgumentNullException.ThrowIfNull(controller);
        HostDistributionHandle handle;
        lock (gate)
        {
            ObjectDisposedException.ThrowIf(closed, this);
            if (!ReferenceEquals(controller.Runtime, runtime))
                throw new InvalidOperationException(HostDistributionDiagnostics.Owner);
            RemoveCompleted();
            RequireLive(controller);
            if (entries.ContainsKey(channel) || controllers.ContainsKey(controller.Self))
                throw new InvalidOperationException(HostDistributionDiagnostics.Attached);
            var entry = new HostDistributionEntry(
                channel,
                checked(++generation),
                controller
            );
            entries.Add(channel, entry);
            controllers.Add(controller.Self, entry);
            handle = new(this, entry);
        }
        _ = controller.Done.Task.ContinueWith(
            _ => Close(handle),
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default
        );

        return handle;
    }

    public HostDistributionLease Acquire(HostDistributionHandle handle)
    {
        lock (gate)
            _ = Require(handle);

        return new(handle);
    }

    public HostDistributionSnapshot Snapshot(HostDistributionHandle handle)
    {
        lock (gate)
        {
            var entry = Require(handle);

            return new(
                entry.Generation,
                entry.Controller.Self,
                entry.InputHandler,
                entry.GetSize,
                entry.NotificationArmed,
                entry.InputPackets,
                entry.OutputPackets,
                entry.QueuedPayloadBytes,
                entry.Output.Count,
                entry.QueuedSegments
            );
        }
    }

    public bool SetGetSize(HostDistributionHandle handle, ProcessContext caller, bool value)
    {
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            bool previous = entry.GetSize;
            entry.GetSize = value;

            return previous;
        }
    }

    public bool GetSize(HostDistributionHandle handle, ProcessContext caller)
    {
        lock (gate)
            return RequireController(handle, caller).GetSize;
    }

    public void SetInputHandler(HostDistributionHandle handle, ProcessContext caller, Pid handler)
    {
        ArgumentNullException.ThrowIfNull(handler);
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            if (!runtime.IsCurrentLocal(handler))
                throw new InvalidOperationException(HostDistributionDiagnostics.Identity);
            entry.InputHandler = handler;
        }
    }

    public void RecordAcceptedHostInput(HostDistributionHandle handle, ProcessContext caller)
    {
        lock (gate)
        {
            var entry = Require(handle);
            RequireCaller(caller);
            if (!caller.Self.Equals(entry.InputHandler))
                throw new InvalidOperationException(HostDistributionDiagnostics.InputHandler);
            entry.InputPackets = checked(entry.InputPackets + 1);
        }
    }

    public void ArmNotification(HostDistributionHandle handle, ProcessContext caller)
    {
        Pid? notify = null;
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            if (!entry.NotificationArmed)
            {
                if (entry.Output.Count != 0)
                    notify = entry.Controller.Self;
                else
                    entry.NotificationArmed = true;
            }
        }
        Notify(notify);
    }

    public bool TryEnqueueFinalizedHostBuffer(HostDistributionHandle handle, HostDistributionBuffer buffer)
    {
        ArgumentNullException.ThrowIfNull(buffer);
        Pid? notify = null;
        lock (gate)
        {
            var entry = Require(handle);
            if (entry.Output.Count >= maximumQueuedBuffers ||
                buffer.PayloadBytes > maximumQueuedPayloadBytes - entry.QueuedPayloadBytes ||
                buffer.SegmentCount > maximumQueuedSegments - entry.QueuedSegments)
                return false;
            entry.Output.Enqueue(buffer);
            entry.QueuedPayloadBytes += buffer.PayloadBytes;
            entry.QueuedSegments += buffer.SegmentCount;
            if (entry.NotificationArmed)
            {
                entry.NotificationArmed = false;
                notify = entry.Controller.Self;
            }
        }
        Notify(notify);

        return true;
    }

    public HostDistributionBuffer? TakeFinalizedHostBuffer(
        HostDistributionHandle handle,
        ProcessContext caller,
        out bool getSize
    )
    {
        lock (gate)
        {
            var entry = RequireController(handle, caller);
            getSize = entry.GetSize;
            if (!entry.Output.TryPeek(out var buffer))
                return null;
            long count = checked(entry.OutputPackets + 1);
            _ = entry.Output.Dequeue();
            entry.QueuedPayloadBytes -= buffer.PayloadBytes;
            entry.QueuedSegments -= buffer.SegmentCount;
            entry.OutputPackets = count;

            return buffer;
        }
    }

    public void Close(HostDistributionHandle handle)
    {
        ArgumentNullException.ThrowIfNull(handle);
        lock (gate)
        {
            if (!ReferenceEquals(handle.Owner, this))
                throw new InvalidOperationException(HostDistributionDiagnostics.ForeignHandle);
            Retire(handle.Entry);
        }
    }

    public void Dispose()
    {
        lock (gate)
        {
            closed = true;
            foreach (var entry in entries.Values.ToArray())
                Retire(entry);
        }
    }

    private HostDistributionEntry Require(HostDistributionHandle handle)
    {
        ArgumentNullException.ThrowIfNull(handle);
        if (!ReferenceEquals(handle.Owner, this))
            throw new InvalidOperationException(HostDistributionDiagnostics.ForeignHandle);
        var entry = handle.Entry;
        if (closed || entry.Closed || !entries.TryGetValue(entry.Channel, out var current) || !ReferenceEquals(current, entry))
            throw new InvalidOperationException(HostDistributionDiagnostics.Closed);
        RequireLive(entry.Controller);

        return entry;
    }

    private HostDistributionEntry RequireController(HostDistributionHandle handle, ProcessContext caller)
    {
        var entry = Require(handle);
        RequireCaller(caller);
        if (!ReferenceEquals(entry.Controller, caller))
            throw new InvalidOperationException(HostDistributionDiagnostics.Controller);

        return entry;
    }

    private void RequireCaller(ProcessContext caller)
    {
        ArgumentNullException.ThrowIfNull(caller);
        if (!ReferenceEquals(caller.Runtime, runtime))
            throw new InvalidOperationException(HostDistributionDiagnostics.Owner);
        RequireLive(caller);
    }

    private void RequireLive(ProcessContext controller)
    {
        if (runtime.IsHaltRequested || controller.Stop.IsCancellationRequested || controller.Done.Task.IsCompleted || !runtime.IsAlive(controller.Self))
            throw new InvalidOperationException(HostDistributionDiagnostics.Closed);
    }

    private void RemoveCompleted()
    {
        foreach (var entry in entries.Values.ToArray())
            if (entry.Controller.Stop.IsCancellationRequested || entry.Controller.Done.Task.IsCompleted || !runtime.IsAlive(entry.Controller.Self))
                Retire(entry);
    }

    private void Retire(HostDistributionEntry entry)
    {
        if (entry.Closed)
            return;
        entry.Closed = true;
        entry.NotificationArmed = false;
        entry.Output.Clear();
        entry.QueuedPayloadBytes = 0;
        entry.QueuedSegments = 0;
        if (entries.TryGetValue(entry.Channel, out var current) && ReferenceEquals(current, entry))
            entries.Remove(entry.Channel);
        if (controllers.TryGetValue(entry.Controller.Self, out current) && ReferenceEquals(current, entry))
            controllers.Remove(entry.Controller.Self);
    }

    private void Notify(Pid? controller)
    {
        if (controller is not null)
            runtime.SendSystem(controller, HostDistributionAtoms.Data);
    }
}

using System.Diagnostics;

namespace Erlang;

public sealed class Mailbox
{
    private readonly object gate = new();
    private readonly LinkedList<Entry> messages = new();
    private LinkedListNode<Entry>? lastPriority;
    private int pending;
    private int admittedCount;
    private long precedenceRevision;
    private long mutationRevision;
    private long pulseRevision;
    private TaskCompletionSource changed = NewSignal();
    internal Func<bool>? HaltRequested { get; init; }
    internal Action? ProcessSignals { get; init; }
    internal Func<ValueTask<long>>? WaitForExecution { get; init; }
    internal Func<bool>? ExecutionBlocked { get; init; }
    internal Action? MessageReceived { get; init; }
    internal Action<Term, Term?>? MessageAdmitted { get; init; }
    internal Action<int>? QueueLengthChanged { get; init; }
    internal Action<Term, SequenceTraceToken?, bool>? TraceReceived { get; init; }
    internal Action? ReceiveTimedOut { get; init; }
    internal Action<bool>? WaitingStateChanged { get; init; }

    private readonly record struct Entry(
        Term Value,
        Func<bool?>? Admission,
        bool Control = false,
        SequenceTraceToken? TraceToken = null,
        bool PreserveTrace = false,
        Term? From = null,
        bool TraceAdmission = true
    );

    private static TaskCompletionSource NewSignal() => new(TaskCreationOptions.RunContinuationsAsynchronously);

    internal void StopForHalt()
    {
        lock (gate)
        {
            mutationRevision++;
            precedenceRevision++;
            messages.Clear();
            pending = 0;
            admittedCount = 0;
            lastPriority = null;
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
    }

    private void ThrowIfHalted()
    {
        if (HaltRequested?.Invoke() == true)
            throw new OperationCanceledException();
    }

    internal void Pulse()
    {
        lock (gate)
        {
            pulseRevision++;
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
    }

    internal async ValueTask WaitForControlCompletion(Task completion, CancellationToken cancellation)
    {
        while (!completion.IsCompleted)
        {
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            Task changedTask;
            lock (gate)
                changedTask = changed.Task;
            ProcessSignals?.Invoke();
            if (completion.IsCompleted)
                break;
            await Task.WhenAny(completion, changedTask).WaitAsync(cancellation);
        }
        cancellation.ThrowIfCancellationRequested();
        await completion;
    }

    public int Count
    {
        get
        {
            ProcessSignals?.Invoke();
            lock (gate)
                return admittedCount;
        }
    }

    internal Action<Term>? IncomingTerm { get; init; }

    public void Send(Term message, bool priority = false)
    {
        SendTraced(
            message,
            null,
            false,
            priority
        );
    }

    internal void SendTraced(
        Term message,
        SequenceTraceToken? token,
        bool preserve = false,
        bool priority = false,
        Term? from = null,
        bool traceAdmission = true
    )
    {
        IncomingTerm?.Invoke(message);
        if (from is not null)
            IncomingTerm?.Invoke(from);
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true)
                return;
            if (priority)
                lastPriority = lastPriority is null ? messages.AddFirst(new Entry(
                    message,
                    null,
                    false,
                    token,
                    preserve,
                    from,
                    traceAdmission
                )) : messages.AddAfter(lastPriority, new Entry(
                    message,
                    null,
                    false,
                    token,
                    preserve,
                    from,
                    traceAdmission
                ));
            else
                messages.AddLast(new Entry(
                    message,
                    null,
                    false,
                    token,
                    preserve,
                    from,
                    traceAdmission
                ));
            mutationRevision++;
            if (priority)
                precedenceRevision++;
            admittedCount++;
            QueueLengthChanged?.Invoke(admittedCount);
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
        if (traceAdmission)
            MessageAdmitted?.Invoke(message, from);
    }

    internal void SendPending(
        Term message,
        Func<bool?> admission,
        SequenceTraceToken? token = null,
        bool preserve = false,
        Term? from = null,
        bool traceAdmission = true
    )
    {
        IncomingTerm?.Invoke(message);
        if (from is not null)
            IncomingTerm?.Invoke(from);
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true)
                return;
            messages.AddLast(new Entry(
                message,
                admission,
                true,
                token,
                preserve,
                from,
                traceAdmission
            ));
            pending++;
            mutationRevision++;
            precedenceRevision++;
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
    }

    internal void AdmitPending()
    {
        var admitted = new List<(Term Message, Term? From)>();
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true || pending == 0)
                return;
            for (var node = messages.First; node is not null;)
            {
                var next = node.Next;
                if (node.Value.Admission is { } admission)
                {
                    pending--;
                    mutationRevision++;
                    precedenceRevision++;
                    node.Value = node.Value with { Admission = null, Control = true };
                    bool? priority = admission();
                    if (priority is null)
                        RemoveNode(node);
                    else
                    {
                        node.Value = node.Value with { Control = false };
                        admittedCount++;
                        QueueLengthChanged?.Invoke(admittedCount);
                        if (node.Value.TraceAdmission)
                            admitted.Add((node.Value.Value, node.Value.From));
                        if (priority.Value)
                        {
                            messages.Remove(node);
                            if (lastPriority is null)
                                messages.AddFirst(node);
                            else
                                messages.AddAfter(lastPriority, node);
                            lastPriority = node;
                        }
                    }
                }
                node = next is not null && next.List == messages ? next : null;
            }
        }
        foreach (var admission in admitted)
            MessageAdmitted?.Invoke(admission.Message, admission.From);
    }

    internal void DiscardPending()
    {
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true || pending == 0)
                return;
            for (var node = messages.First; node is not null;)
            {
                var next = node.Next;
                if (node.Value.Admission is not null)
                    RemoveNode(node);
                node = next;
            }
            pending = 0;
        }
    }

    public bool RemoveFirst(Func<Term, bool> predicate)
    {
        ProcessSignals?.Invoke();
        while (true)
        {
            LinkedListNode<Entry>? node;
            long revision;
            lock (gate)
            {
                node = messages.First;
                revision = precedenceRevision;
            }
            bool retry = false;
            while (node is not null)
            {
                Entry candidate;
                lock (gate)
                {
                    if (revision != precedenceRevision || !ReferenceEquals(node.List, messages))
                    {
                        retry = true;
                        break;
                    }
                    if (!IsAdmitted(node))
                    {
                        node = node.Next;
                        continue;
                    }
                    candidate = node.Value;
                }
                bool matched = predicate(candidate.Value);
                lock (gate)
                {
                    if (revision != precedenceRevision || !IsAdmitted(node))
                    {
                        retry = true;
                        break;
                    }
                    if (matched)
                    {
                        RemoveNode(node);

                        return true;
                    }
                    node = node.Next;
                }
            }
            if (!retry)
                return false;
            ProcessSignals?.Invoke();
        }
    }

    public int Remove(Func<Term, bool> predicate)
    {
        ProcessSignals?.Invoke();
        while (true)
        {
            (LinkedListNode<Entry> Node, Entry Value)[] candidates;
            long revision;
            lock (gate)
            {
                candidates = CaptureAdmitted();
                revision = mutationRevision;
            }
            var matched = new List<LinkedListNode<Entry>>();
            foreach (var candidate in candidates)
            {
                if (predicate(candidate.Value.Value))
                    matched.Add(candidate.Node);
            }
            lock (gate)
            {
                if (revision == mutationRevision && candidates.All(candidate => IsAdmitted(candidate.Node)))
                {
                    foreach (var node in matched)
                        RemoveNode(node);

                    return matched.Count;
                }
            }
            ProcessSignals?.Invoke();
        }
    }

    private (LinkedListNode<Entry> Node, Entry Value)[] CaptureAdmitted()
    {
        var captured = new List<(LinkedListNode<Entry>, Entry)>();
        for (var node = messages.First; node is not null; node = node.Next)
        {
            if (IsAdmitted(node))
                captured.Add((node, node.Value));
        }

        return captured.ToArray();
    }

    private bool IsAdmitted(LinkedListNode<Entry> node) =>
        ReferenceEquals(node.List, messages) && !node.Value.Control && node.Value.Admission is null;

    internal async Task WaitForMessage(CancellationToken cancellation)
    {
        try
        {
            await WaitForMessageCore(cancellation);
        }
        finally
        {
            WaitingStateChanged?.Invoke(false);
        }
    }

    private async Task WaitForMessageCore(CancellationToken cancellation)
    {
        while (true)
        {
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            ProcessSignals?.Invoke();
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            if (WaitForExecution is not null)
                await WaitForExecution();
            Task signal;
            bool retry;
            lock (gate)
            {
                retry = pending != 0;
                if (!retry && messages.Count != 0)
                    return;
                signal = changed.Task;
            }
            if (retry || ExecutionBlocked?.Invoke() == true)
                continue;
            WaitingStateChanged?.Invoke(true);
            await signal.WaitAsync(cancellation);
        }
    }

    public async ValueTask<T?> ReceiveAsync<T>(Func<Term, T?> select, TimeSpan? timeout, CancellationToken cancellation = default) where T : class
    {
        try
        {
            return await ReceiveCore(select, timeout, cancellation);
        }
        finally
        {
            WaitingStateChanged?.Invoke(false);
        }
    }

    private async ValueTask<T?> ReceiveCore<T>(Func<Term, T?> select, TimeSpan? timeout, CancellationToken cancellation) where T : class
    {
        if (timeout < TimeSpan.Zero)
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        long start = Stopwatch.GetTimestamp();
        bool firstBatch = true;
        bool previousConflict = false;
        LinkedListNode<Entry>? resumeAfter = null;
        long resumeRevision = 0;
        while (true)
        {
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            ProcessSignals?.Invoke();
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            if (WaitForExecution is not null)
                start += await WaitForExecution();
            if (!firstBatch && timeout is { } finiteTimeout && finiteTimeout > TimeSpan.Zero && Stopwatch.GetElapsedTime(start) >= finiteTimeout)
            {
                ReceiveTimedOut?.Invoke();

                return null;
            }
            firstBatch = false;
            previousConflict = false;
            Task signal;
            bool retry;
            T? selected = null;
            Entry received = default;
            LinkedListNode<Entry>? node;
            long revision;
            long capturedPulse;
            LinkedListNode<Entry>? capturedTail;
            lock (gate)
            {
                retry = pending != 0;
                node = retry ? null : resumeAfter is not null && resumeRevision == precedenceRevision && IsAdmitted(resumeAfter)
                    ? resumeAfter.Next : messages.First;
                revision = precedenceRevision;
                capturedPulse = pulseRevision;
                capturedTail = messages.Last;
                signal = changed.Task;
            }
            resumeAfter = null;
            while (node is not null)
            {
                Entry candidate;
                lock (gate)
                {
                    if (revision != precedenceRevision || pending != 0 || !ReferenceEquals(node.List, messages))
                    {
                        retry = true;
                        break;
                    }
                    if (!IsAdmitted(node))
                    {
                        node = node.Next;
                        continue;
                    }
                    candidate = node.Value;
                }
                T? match = select(candidate.Value);
                ThrowIfHalted();
                cancellation.ThrowIfCancellationRequested();
                lock (gate)
                {
                    ThrowIfHalted();
                    cancellation.ThrowIfCancellationRequested();
                    if (revision != precedenceRevision || pending != 0 || !IsAdmitted(node)
                        || ExecutionBlocked?.Invoke() == true)
                    {
                        retry = true;
                        break;
                    }
                    if (match is not null)
                    {
                        selected = match;
                        received = candidate;
                        RemoveNode(node);
                        break;
                    }
                    if (ReferenceEquals(node, capturedTail))
                    {
                        resumeAfter = node;
                        resumeRevision = revision;
                        node = null;
                    }
                    else
                    {
                        node = node.Next;
                    }
                }
            }
            if (selected is null)
            {
                lock (gate)
                {
                    previousConflict = revision != precedenceRevision || capturedPulse != pulseRevision || pending != 0;
                    retry |= previousConflict || !ReferenceEquals(capturedTail, messages.Last) || !ReferenceEquals(signal, changed.Task);
                    if (previousConflict)
                        resumeAfter = null;
                    signal = changed.Task;
                }
            }
            if (selected is not null)
            {
                MessageReceived?.Invoke();
                TraceReceived?.Invoke(received.Value, received.TraceToken, received.PreserveTrace);

                return selected;
            }
            if (timeout == TimeSpan.Zero && retry && !previousConflict && ExecutionBlocked?.Invoke() != true)
            {
                ReceiveTimedOut?.Invoke();

                return null;
            }
            if (retry || ExecutionBlocked?.Invoke() == true)
                continue;
            TimeSpan? remaining = timeout - Stopwatch.GetElapsedTime(start);
            if (remaining <= TimeSpan.Zero)
            {
                ReceiveTimedOut?.Invoke();

                return null;
            }
            try
            {
                if (remaining is { } finite)
                {
                    WaitingStateChanged?.Invoke(true);
                    await signal.WaitAsync(
                        finite > TimeSpan.FromMilliseconds(MailboxWaitParameters.MaximumSegmentMilliseconds) ? TimeSpan.FromMilliseconds(MailboxWaitParameters.MaximumSegmentMilliseconds) : finite,
                        cancellation
                    );
                }
                else
                {
                    WaitingStateChanged?.Invoke(true);
                    await signal.WaitAsync(cancellation);
                }
            }
            catch (TimeoutException)
            {
                continue;
            }
        }
    }

    private void RemoveNode(LinkedListNode<Entry> node)
    {
        bool ordinary = !node.Value.Control && node.Value.Admission is null;
        mutationRevision++;
        precedenceRevision++;
        if (ordinary)
            admittedCount--;
        if (ReferenceEquals(node, lastPriority))
            lastPriority = node.Previous;
        messages.Remove(node);
        if (ordinary)
            QueueLengthChanged?.Invoke(admittedCount);
    }

    internal IReadOnlyList<Term> Snapshot()
    {
        lock (gate)
            return messages.Where(entry => !entry.Control).Select(entry => entry.Value).ToArray();
    }
}

namespace Erlang;

public sealed partial class ModuleRegistry
{
    private ProcessRuntime? owningRuntime;

    internal void AttachRuntime(ProcessRuntime runtime)
    {
        lock (gate)
        {
            if (owningRuntime is not null && !ReferenceEquals(owningRuntime, runtime))
                throw new ArgumentException(RuntimeExternalTermDiagnostics.ForeignRegistry, nameof(runtime));
            owningRuntime = runtime;
        }
    }

    internal EtfDecodeOptions PreparationDecodeOptions()
    {
        ProcessRuntime? runtime = owningRuntime;
        if (runtime is null)
            return new();
        var options = new EtfDecodeOptions { LocalSeed = runtime.LocalTermSeed };

        return options with { NodeAdmission = epochs => runtime.AdmitExternalDecode(options, epochs) };
    }

    private void ObserveDescriptor(ModuleCodeDescriptor descriptor)
    {
        ProcessRuntime? runtime = owningRuntime;
        if (runtime is null)
            return;
        runtime.ObserveIncomingTerm(descriptor.Compilation);
        if (descriptor.Attributes is not null)
            runtime.ObserveIncomingTerm(descriptor.Attributes);
        foreach (var record in descriptor.NativeRecords)
            foreach (var field in record.Fields)
                if (field.Value is not null)
                    runtime.ObserveIncomingTerm(field.Value);
    }
}

namespace Erlang;

public sealed partial class ModuleRegistry
{
    public PreparedBeamImage PrepareBeam(ReadOnlyMemory<byte> bytes)
    {
        byte[] owned = bytes.ToArray();
        EtfDecodeOptions decoding = PreparationDecodeOptions();
        BeamLinkedCode code = BeamLinkedCodeReader.Read(BeamStructureReader.Read(owned, decoding));
        if (code.OnLoadEntryLabel is int callbackLabel)
        {
            BeamLinkedFunction callback = code.Functions.Single(function => function.EntryLabel == callbackLabel);
            BeamRegisterValidation.Validate(code, callback);
        }
        BeamPreparedMetadata metadata = BeamPublicationMetadata.Read(code, decoding);
        if (code.OnLoadEntryLabel is not null)
            BeamOnLoadMetadata.RequireSupported(metadata);
        var bodies = new List<ErlangFunction>();
        foreach (BeamLinkedFunction function in code.Exports)
        {
            if (BeamGeneratedMetadata.IsGenerated(code, function))
            {
                bodies.Add((context, arguments) => BeamGeneratedMetadata.Invoke(context, function.Module, arguments));
            }
            else
            {
                BeamRegisterValidation.Validate(code, function);
                bodies.Add((context, arguments) => BeamRegisterInterpreter.Execute(
                    context,
                    code,
                    function.Name,
                    Array.AsReadOnly(arguments.ToArray())
                ));
            }
        }

        return new PreparedBeamImage(
            this,
            code,
            metadata,
            bodies.AsReadOnly()
        );
    }

    public BeamPublicationResult PublishPreparedBeam(params PreparedBeamImage[] images)
    {
        ArgumentNullException.ThrowIfNull(images);
        PreparedBeamImage[] owned = images.ToArray();
        lock (gate)
        {
            foreach (PreparedBeamImage image in owned)
            {
                ArgumentNullException.ThrowIfNull(image);
                if (!ReferenceEquals(image.Owner, this))
                    throw new ArgumentException(BeamPreparationNames.ForeignImage, nameof(images));
                if (image.Consumed)
                    throw new InvalidOperationException(BeamPreparationNames.ConsumedImage);
                if (image.HasOnLoad)
                    throw new InvalidOperationException(BeamOnLoadDiagnostics.RequiresStaging);
                if (pendingBeamImages.ContainsKey(image.Name))
                    throw new InvalidOperationException(BeamOnLoadDiagnostics.BusyModule);
            }
            var seen = new HashSet<string>(StringComparer.Ordinal);
            string[] duplicates = owned.Where(image => !seen.Add(image.Name)).Select(image => image.Name).Reverse().ToArray();
            if (duplicates.Length != 0)
                return new(BeamPublicationStatus.Duplicated, Array.AsReadOnly(duplicates));
            string[] blocked = owned.Where(image => loadedModules.ContainsKey(image.Name) && oldCode.ContainsKey(image.Name))
                .Select(image => image.Name).Reverse().ToArray();
            if (blocked.Length != 0)
                return new(BeamPublicationStatus.NotPurged, Array.AsReadOnly(blocked));
            Apply(registry =>
            {
                foreach (PreparedBeamImage image in owned)
                {
                    if (loadedModules.ContainsKey(image.Name))
                        registry.DeleteModule(image.Name);
                    for (int index = 0; index < image.Code.Exports.Count; index++)
                    {
                        BeamLinkedFunction function = image.Code.Exports[index];
                        registry.Register(
                            image.Name,
                            function.Name,
                            function.Arity,
                            image.Bodies[index]
                        );
                    }
                    registry.PublishModuleCode(image.Name, image.Descriptor);
                }
            });
            foreach (PreparedBeamImage image in owned)
                image.Consumed = true;

            return new(BeamPublicationStatus.Published, Array.AsReadOnly(owned.Select(image => image.Name).ToArray()));
        }
    }

    internal bool IsPreparedBeamConsumed(PreparedBeamImage image)
    {
        lock (gate)
            return image.Consumed;
    }
}

using System.Numerics;

namespace Erlang;

public sealed partial class ModuleRegistry
{
    private readonly object gate = new();
    private readonly Dictionary<(string Module, string Function, int Arity), ErlangFunction> functions = new();
    private readonly Dictionary<string, Atom> loadedModules = new(StringComparer.Ordinal);
    private readonly Dictionary<string, Atom> preloadedModules = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ModuleCodeDescriptor> codeDescriptors = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ModuleInformationSnapshot> informationSnapshots = new(StringComparer.Ordinal);
    private readonly HashSet<string> knownModules = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ModuleCodeSnapshot> oldCode = new(StringComparer.Ordinal);
    private readonly Dictionary<(string Module, string Function, int Arity), object> sourceOwners = new();
    private readonly Dictionary<string, ModuleCodeImage> codeImages = new(StringComparer.Ordinal);
    private readonly System.Runtime.CompilerServices.ConditionalWeakTable<ModuleCodeImage, ModuleCodePurgeState> purgeStates = new();

    public SourceCodeLease ReserveSourceCode(ProcessContext context, ModuleCodeImage image)
    {
        lock (gate)
        {
            var state = purgeStates.GetOrCreateValue(image);
            if (state.Retired || state.Pending is not null && !context.IsExecutingCode(image))
                throw new ErlangException(ErlangErrorReasons.UndefinedFunction);

            return context.ReserveSourceCode(image);
        }
    }

    public async ValueTask<SourceCodeLease> AcquireSourceCode(ProcessContext context, ModuleCodeImage image)
    {
        while (true)
        {
            Task? pending;
            lock (gate)
            {
                var state = purgeStates.GetOrCreateValue(image);
                if (state.Retired)
                    throw new ErlangException(ErlangErrorReasons.UndefinedFunction);
                pending = state.Pending?.Task;
                if (pending is null || context.IsExecutingCode(image))
                    return context.ReserveSourceCode(image);
            }
            await context.Mailbox.WaitForControlCompletion(pending, context.Cancellation);
        }
    }

    public async ValueTask<SourceFunctionAdmission> AdmitSourceFunction(
        ProcessContext context,
        string module,
        BitString fingerprint,
        object owner,
        ModuleCodeImage? capturedImage,
        FunctionTerm function
    )
    {
        while (true)
        {
            Task? pending;
            lock (gate)
            {
                var current = SourceForCode(module, fingerprint);
                if (current is not null && current.Owner.GetType() != owner.GetType())
                    current = null;
                var image = current?.Image ?? capturedImage;
                var selectedOwner = current?.Owner ?? owner;
                if (image is null)
                    return new(selectedOwner, null, null);
                var state = purgeStates.GetOrCreateValue(image);
                if (state.Retired)
                    throw new ErlangException(loadedModules.ContainsKey(module) ? Term.Tuple(Term.A(ErlangErrorReasons.BadFunction), function) : Term.A(ErlangErrorReasons.UndefinedFunction));
                pending = state.Pending?.Task;
                if (pending is null)
                    return new(selectedOwner, image, context.ReserveSourceCode(image));
            }
            await context.Mailbox.WaitForControlCompletion(pending, context.Cancellation);
        }
    }

    internal ModuleCodeImage? PreparePurge(string module)
    {
        lock (gate)
        {
            if (!oldCode.TryGetValue(module, out var old))
                return null;
            var state = purgeStates.GetOrCreateValue(old.Image);
            if (state.Pending is not null)
                throw new InvalidOperationException();
            state.Pending = new(TaskCreationOptions.RunContinuationsAsynchronously);

            return old.Image;
        }
    }

    public Task? PendingPurge(ModuleCodeImage image)
    {
        lock (gate)
            return purgeStates.GetOrCreateValue(image).Pending?.Task;
    }

    internal void FinishPurge(string module, ModuleCodeImage image, bool complete)
    {
        lock (gate)
        {
            var state = purgeStates.GetOrCreateValue(image);
            var pending = state.Pending ?? throw new InvalidOperationException();
            if (complete)
            {
                if (!oldCode.TryGetValue(module, out var old) || !ReferenceEquals(old.Image, image))
                    throw new InvalidOperationException();
                oldCode.Remove(module);
                state.Retired = true;
            }
            state.Pending = null;
            pending.TrySetResult();
        }
    }

    public void Register(
        string module,
        string function,
        int arity,
        ErlangFunction body
    )
    {
        AtomNameRegistry.Observe(module);
        AtomNameRegistry.Observe(function);
        lock (gate)
        {
            functions.Add((module, function, arity), body);
            intrinsicBindings.Remove((module, function, arity));
            PublishModule(module);
            informationSnapshots.Remove(module);
        }
    }

    public void RegisterSource(
        string module,
        string function,
        int arity,
        ErlangFunction body,
        object sourceOwner
    )
    {
        ArgumentNullException.ThrowIfNull(sourceOwner);
        lock (gate)
        {
            Register(
                module,
                function,
                arity,
                body
            );
            sourceOwners.Add((module, function, arity), sourceOwner);
        }
    }

    public object? SourceOwner(string module, string function, int arity)
    {
        lock (gate)
            return sourceOwners.GetValueOrDefault((module, function, arity));
    }

    public SourceCodeEntry? SourceEntry(string module, string function, int arity)
    {
        lock (gate)
        {
            if (!sourceOwners.TryGetValue((module, function, arity), out var owner))
                return null;

            return new SourceCodeEntry(owner, codeImages[module]);
        }
    }

    public ModuleCodeImage? CurrentCodeImage(string module)
    {
        lock (gate)
            return codeImages.GetValueOrDefault(module);
    }

    public SourceCodeEntry? SourceForCode(string module, BitString fingerprint)
    {
        lock (gate)
        {
            if (!codeDescriptors.TryGetValue(module, out var descriptor) || descriptor.SourceOwner is null || !descriptor.Fingerprint.Equals(fingerprint) ||
                !sourceOwners.Any(entry => entry.Key.Module == module && ReferenceEquals(entry.Value, descriptor.SourceOwner)))
                return null;

            return new SourceCodeEntry(descriptor.SourceOwner, codeImages[module]);
        }
    }

    public ModuleCodeImage? SourceImage(string module, object owner)
    {
        lock (gate)
        {
            if (sourceOwners.Any(entry => entry.Key.Module == module && ReferenceEquals(entry.Value, owner)))
                return codeImages[module];
            if (oldCode.TryGetValue(module, out var old) && old.SourceOwners.Any(value => ReferenceEquals(value, owner)))
                return old.Image;

            return null;
        }
    }

    public bool IsExecutingOldCode(ProcessContext context, string module)
    {
        lock (gate)
            return oldCode.TryGetValue(module, out var old) && context.IsExecutingCode(old.Image);
    }

    internal Term CallMatchSpecGuard(ProcessContext context, string function, Term[] arguments)
    {
        if (!MatchSpecOperations.Pure.Contains((function, arguments.Length)))
            throw MatchSpecNames.UnsupportedAction(function, arguments.Length);
        if (function == ErlangModuleNames.IsInteger && arguments.Length == 3)
        {
            if (arguments[1] is not Integer minimum || arguments[2] is not Integer maximum)
                throw new ErlangException(ErlangErrorReasons.BadArgument);

            return CoreModules.Boolean(arguments[0] is Integer number && number.Value >= minimum.Value && number.Value <= maximum.Value);
        }
        ErlangFunction body;
        lock (gate)
        {
            if (!functions.TryGetValue((ErlangModuleNames.Module, function, arguments.Length), out body!))
                throw MatchSpecNames.UnsupportedAction(function, arguments.Length);
        }

        ValueTask<Term> pending = body(context, arguments);
        if (!pending.IsCompleted)
            throw MatchSpecNames.UnsupportedAction(function, arguments.Length);

        return pending.GetAwaiter().GetResult();
    }

    public ValueTask<Term> Call(
        ProcessContext context,
        string module,
        string function,
        params Term[] arguments
    )
    {
        context.Runtime.ThrowIfHalted();
        foreach (Term argument in arguments)
            context.Runtime.ObserveIncomingTerm(argument);
        ErlangFunction? body;
        ModuleCodeImage? image;
        IDisposable? code;
        lock (gate)
        {
            functions.TryGetValue((module, function, arguments.Length), out body);
            var signature = (module, function, arguments.Length);
            ModuleCodeImage? currentImage = codeImages.GetValueOrDefault(module);
            image = sourceOwners.ContainsKey(signature) || IsIntrinsic(signature, body, currentImage) ? null : currentImage;
            code = image is null || body is null ? null : context.EnterSourceCode(image, body);
        }
        if (body is null)
            throw new ErlangException(ErlangErrorReasons.UndefinedFunction);
        ProcessTraceInvocation? invocation = null;
        if (image is null)
        {
            invocation = context.Runtime.ProcessTracing.Called(
                context,
                module,
                function,
                arguments
            );
            context.SavedCalls.Record(module, function, arguments.Length);
            try
            {
                return GuardHaltBoundary(context.Runtime.ProcessTracing.Complete(context, invocation, body(context, arguments)), context);
            }
            catch (ErlangException exception)
            {
                context.Runtime.ProcessTracing.Failed(context, invocation, exception);
                throw;
            }
        }
        try
        {
            invocation = context.Runtime.ProcessTracing.Called(
                context,
                module,
                function,
                arguments
            );
            context.SavedCalls.Record(module, function, arguments.Length);
            ValueTask<Term> pending = context.Runtime.ProcessTracing.Complete(context, invocation, body(context, arguments));
            if (pending.IsCompletedSuccessfully)
            {
                context.Runtime.ThrowIfHalted();
                context.Runtime.ObserveIncomingTerm(pending.Result);
                code!.Dispose();

                return pending;
            }

            return AwaitCallback(pending, code!, context);
        }
        catch (Exception exception)
        {
            code!.Dispose();
            if (exception is ErlangException failure)
                context.Runtime.ProcessTracing.Failed(context, invocation, failure);
            throw;
        }
        finally
        {
            context.RestoreSourceCodeFlow(code!);
        }
    }

    private static ValueTask<Term> GuardHaltBoundary(ValueTask<Term> pending, ProcessContext context)
    {
        if (pending.IsCompletedSuccessfully)
        {
            context.Runtime.ThrowIfHalted();
            context.Runtime.ObserveIncomingTerm(pending.Result);

            return pending;
        }

        return AwaitHaltBoundary(pending, context);
    }

    private static async ValueTask<Term> AwaitHaltBoundary(ValueTask<Term> pending, ProcessContext context)
    {
        Term result = await pending;
        context.Runtime.ThrowIfHalted();
        context.Runtime.ObserveIncomingTerm(result);

        return result;
    }

    private static async ValueTask<Term> AwaitCallback(ValueTask<Term> pending, IDisposable code, ProcessContext context)
    {
        using (code)
            return await AwaitHaltBoundary(pending, context);
    }

    public bool HasExport(string module, string function, int arity)
    {
        lock (gate)
            return functions.ContainsKey((module, function, arity));
    }

    public void PublishModule(string module)
    {
        AtomNameRegistry.Observe(module);
        lock (gate)
        {
            knownModules.Add(module);
            if (!loadedModules.ContainsKey(module))
                loadedModules.Add(module, Term.A(module));
            if (!codeImages.ContainsKey(module))
                codeImages.Add(module, new ModuleCodeImage(module));
        }
    }

    public bool IsModuleLoaded(string module)
    {
        lock (gate)
            return loadedModules.ContainsKey(module);
    }

    public bool HasOldCode(string module)
    {
        lock (gate)
            return oldCode.ContainsKey(module);
    }

    public Term DeleteModule(string module)
    {
        lock (gate)
        {
            if (!knownModules.Contains(module))
                return Term.A(ModuleCodeLifecycleNames.UnknownModule);
            if (oldCode.ContainsKey(module))
                throw new ErlangException(ErlangErrorReasons.BadArgument);
            var entries = functions.Where(entry => entry.Key.Module == module).Select(entry => (entry.Key, entry.Value)).ToArray();
            codeDescriptors.TryGetValue(module, out var descriptor);
            if (entries.Length != 0 || descriptor is not null)
                oldCode.Add(
                    module,
                    new ModuleCodeSnapshot(
                        Array.AsReadOnly(entries),
                        descriptor,
                        codeImages[module],
                        Array.AsReadOnly(sourceOwners.Where(entry => entry.Key.Module == module).Select(entry => entry.Value).ToArray())
                    )
                );
            foreach (var entry in entries)
            {
                functions.Remove(entry.Key);
                intrinsicBindings.Remove(entry.Key);
                sourceOwners.Remove(entry.Key);
            }
            loadedModules.Remove(module);
            codeDescriptors.Remove(module);
            codeImages.Remove(module);
            informationSnapshots.Remove(module);

            return Term.A(ErlangBooleanAtoms.True);
        }
    }

    public NativeRecordDefinition? NativeRecordDefinition(string module, string name)
    {
        lock (gate)
        {
            return codeDescriptors.TryGetValue(module, out var descriptor) ? descriptor.NativeRecords.FirstOrDefault(definition => definition.Name == name) : null;
        }
    }

    public void PublishModuleCode(string module, ModuleCodeDescriptor descriptor)
    {
        ArgumentNullException.ThrowIfNull(descriptor);
        ObserveDescriptor(descriptor);
        lock (gate)
        {
            PublishModule(module);
            codeDescriptors[module] = descriptor;
            informationSnapshots.Remove(module);
        }
    }

    public Term ModuleInformation(string module, string? key = null)
    {
        lock (gate)
        {
            if (!informationSnapshots.TryGetValue(module, out var snapshot))
            {
                if (!loadedModules.ContainsKey(module))
                    throw new ErlangException(ErlangErrorReasons.BadArgument);
                var entries = functions.Where(entry => entry.Key.Module == module).Select(entry => (Signature: (entry.Key.Function, entry.Key.Arity), Body: entry.Value)).ToArray();
                codeDescriptors.TryGetValue(module, out var descriptor);
                if (descriptor is null && entries.Length == 0)
                    throw new ErlangException(ErlangErrorReasons.BadArgument);
                var exports = entries.Select(entry => entry.Signature).ToArray();
                var signatures = descriptor is null ? exports : descriptor.Functions.Concat(exports);
                var additional = descriptor is null ? entries : entries.Where(entry => !descriptor.Exports.Contains(entry.Signature)).ToArray();
                BitString fingerprint = descriptor is not null && additional.Length == 0 ? descriptor.Fingerprint : ModuleCodeFingerprints.Registered(module, additional, descriptor?.Fingerprint);
                Term compilation = descriptor?.Compilation ?? ModuleCodeFingerprints.Compilation(typeof(ModuleRegistry));
                snapshot = new ModuleInformationSnapshot(
                    module,
                    exports,
                    signatures,
                    fingerprint,
                    compilation,
                    descriptor?.Attributes,
                    descriptor?.AttributePolicy ?? ModuleAttributePolicy.AddDefaultVersion
                );
                informationSnapshots.Add(module, snapshot);
            }

            return key is null ? snapshot.All : snapshot.Field(key);
        }
    }

    public IReadOnlyCollection<string> LoadedModules
    {
        get
        {
            lock (gate)
                return Array.AsReadOnly(loadedModules.Keys.ToArray());
        }
    }

    public void InstallPreloaded(Action<ModuleRegistry> configure)
    {
        ArgumentNullException.ThrowIfNull(configure);
        Apply(target =>
        {
            var previous = loadedModules.Keys.ToHashSet(StringComparer.Ordinal);
            configure(target);
            foreach (var module in loadedModules)
            {
                if (!previous.Contains(module.Key))
                    preloadedModules.TryAdd(module.Key, module.Value);
            }
        });
    }

    public IReadOnlyCollection<string> PreloadedModules
    {
        get
        {
            lock (gate)
                return Array.AsReadOnly(preloadedModules.Keys.ToArray());
        }
    }

    internal Term PreloadedModuleList()
    {
        lock (gate)
        {
            Term result = Nil.Value;
            foreach (Atom module in preloadedModules.Values)
                result = new Cons(module, result);

            return result;
        }
    }

    internal Term LoadedModuleList()
    {
        lock (gate)
        {
            Term result = Nil.Value;
            foreach (string module in loadedModules.Keys.Concat(oldCode.Keys).Distinct(StringComparer.Ordinal))
                result = new Cons(Term.A(module), result);

            return result;
        }
    }

    public void Apply(Action<ModuleRegistry> configure)
    {
        ArgumentNullException.ThrowIfNull(configure);
        lock (gate)
        {
            var previous = new Dictionary<(string Module, string Function, int Arity), ErlangFunction>(functions);
            var previousIntrinsics = new Dictionary<(string Module, string Function, int Arity), IntrinsicBinding>(intrinsicBindings);
            var previousModules = new Dictionary<string, Atom>(loadedModules, StringComparer.Ordinal);
            var previousPreloaded = new Dictionary<string, Atom>(preloadedModules, StringComparer.Ordinal);
            var previousDescriptors = new Dictionary<string, ModuleCodeDescriptor>(codeDescriptors, StringComparer.Ordinal);
            var previousInformation = new Dictionary<string, ModuleInformationSnapshot>(informationSnapshots, StringComparer.Ordinal);
            var previousKnown = knownModules.ToArray();
            var previousOld = new Dictionary<string, ModuleCodeSnapshot>(oldCode, StringComparer.Ordinal);
            var previousOwners = new Dictionary<(string Module, string Function, int Arity), object>(sourceOwners);
            var previousImages = new Dictionary<string, ModuleCodeImage>(codeImages, StringComparer.Ordinal);
            try
            {
                configure(this);
            }
            catch
            {
                intrinsicBindings.Clear();
                foreach (var entry in previousIntrinsics)
                    intrinsicBindings.Add(entry.Key, entry.Value);
                functions.Clear();
                foreach (var entry in previous)
                    functions.Add(entry.Key, entry.Value);
                loadedModules.Clear();
                foreach (var module in previousModules)
                    loadedModules.Add(module.Key, module.Value);
                preloadedModules.Clear();
                foreach (var module in previousPreloaded)
                    preloadedModules.Add(module.Key, module.Value);
                codeDescriptors.Clear();
                foreach (var entry in previousDescriptors)
                    codeDescriptors.Add(entry.Key, entry.Value);
                informationSnapshots.Clear();
                foreach (var entry in previousInformation)
                    informationSnapshots.Add(entry.Key, entry.Value);
                knownModules.Clear();
                knownModules.UnionWith(previousKnown);
                oldCode.Clear();
                foreach (var entry in previousOld)
                    oldCode.Add(entry.Key, entry.Value);
                sourceOwners.Clear();
                foreach (var entry in previousOwners)
                    sourceOwners.Add(entry.Key, entry.Value);
                codeImages.Clear();
                foreach (var entry in previousImages)
                    codeImages.Add(entry.Key, entry.Value);
                throw;
            }
        }
    }

    public IReadOnlyCollection<(string Module, string Function, int Arity)> Exports
    {
        get
        {
            lock (gate)
                return Array.AsReadOnly(functions.Keys.ToArray());
        }
    }
}

namespace Erlang;

public sealed class ProcessContext : ITermExecutionContext
{
    internal ProcessContext(
        ProcessRuntime runtime,
        Pid pid,
        Term? initialCall = null
    )
    {
        Runtime = runtime;
        InitialCall = initialCall ?? ProcessInfoAtoms.Undefined;
        Self = pid;
        GroupLeader = pid;
        Mailbox = new()
        {
            IncomingTerm = Runtime.ObserveIncomingTerm,
            HaltRequested = () => Runtime.IsHaltRequested,
            ProcessSignals = () => Runtime.AdmitSignals(this),
            WaitForExecution = WaitIfSuspended,
            ExecutionBlocked = () => SuspensionRequested,
            MessageReceived = SavedCalls.Received,
            MessageAdmitted = (message, from) => Runtime.ProcessTracing.Admitted(this, message, from),
            TraceReceived = (message, token, preserve) => Runtime.SequenceTracing.Received(
                this,
                message,
                token,
                preserve
            ),
            ReceiveTimedOut = () =>
            {
                SavedCalls.TimedOut();
                Runtime.ProcessTracing.Admitted(this, Term.A(ProcessTraceNames.Timeout), Term.A(ProcessTraceNames.ClockService));
            },
            WaitingStateChanged = waiting => WaitingForMessage = waiting,
            QueueLengthChanged = count => Runtime.SystemMonitoring.QueueChanged(Self, count)
        };
    }

    internal CancellationTokenSource Stop { get; } = new();
    internal Pid GroupLeader { get; set; }
    internal TaskCompletionSource<Term> Done { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
    internal TaskCompletionSource Unwound { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
    internal HashSet<Pid> Links { get; } = new();
    internal Dictionary<Pid, ProcessLinkIdentity> LinkIdentities { get; } = new();
    internal Dictionary<ProcessLinkIdentity, Pid> PendingLinkOrigins { get; } = new();
    internal HashSet<PortTerm> PortLinks { get; } = new();
    internal HashSet<PortTerm> PriorityPortLinks { get; } = new();
    internal HashSet<Pid> PriorityLinks { get; } = new();
    internal bool Terminated;
    internal volatile bool SuspensionRequested;
    internal HashSet<ProcessCodeRequest> PendingCodeChecks { get; } = new();
    internal HashSet<ProcessGarbageCollectionRequest> PendingGarbageCollections { get; } = new();
    internal HashSet<ProcessInfoRequest> PendingInfoRequests { get; } = new();
    internal HashSet<ProcessDisplayRequest> PendingDisplayRequests { get; } = new();
    internal volatile bool WaitingForMessage;
    internal volatile bool ExecutionStarted;
    internal volatile bool Yielding;
    internal HashSet<ProcessSavedCallRequest> PendingSavedCallRequests { get; } = new();
    internal ProcessSavedCalls SavedCalls { get; } = new();
    internal SequenceTraceState SequentialTrace { get; } = new();
    private int reductions;
    private long cumulativeReductions;
    internal Term InitialCall { get; }
    internal Atom ErrorHandler { get; } = ProcessInfoLogicalAtoms.DefaultErrorHandler;
    internal Atom SchedulingPriority { get; } = ProcessInfoLogicalAtoms.NormalPriority;
    internal long CumulativeReductions => Interlocked.Read(ref cumulativeReductions);
    private readonly AsyncLocal<ErlangExecutionFrame?> executionFrame = new();
    private ErlangExecutionFrame? visibleExecutionFrame;
    private readonly object codeGate = new();
    private readonly Dictionary<ModuleCodeImage, int> activeCode = new();
    private readonly AsyncLocal<SourceExecution?> sourceExecution = new();

    private sealed record SourceExecution(ModuleCodeImage Image, object Owner, SourceExecution? Parent);

    private sealed class SourceExecutionScope(ProcessContext context, SourceExecution current) : IDisposable
    {
        private int disposed;

        public void RestoreFlow() => context.sourceExecution.Value = current.Parent;

        public void Dispose()
        {
            if (Interlocked.Exchange(ref disposed, 1) != 0)
                return;
            RestoreFlow();
        }
    }

    private sealed class SourceCodeScope(SourceCodeLease lease, IDisposable flow) : IDisposable
    {
        public void RestoreFlow() => ((SourceExecutionScope)flow).RestoreFlow();

        public void Dispose()
        {
            flow.Dispose();
            lease.Dispose();
        }
    }

    public ModuleCodeImage? ExecutingSourceImage(object owner)
    {
        var current = sourceExecution.Value;

        return current is not null && ReferenceEquals(current.Owner, owner) ? current.Image : null;
    }

    public IDisposable EnterSourceCode(ModuleCodeImage image, object owner)
    {
        ArgumentNullException.ThrowIfNull(image);
        ArgumentNullException.ThrowIfNull(owner);
        var lease = Runtime.Modules.ReserveSourceCode(this, image);

        return new SourceCodeScope(lease, lease.Attach(owner));
    }

    internal SourceCodeLease ReserveSourceCode(ModuleCodeImage image)
    {
        lock (codeGate)
            activeCode[image] = activeCode.GetValueOrDefault(image) + 1;

        return new SourceCodeLease(this, image);
    }

    internal IDisposable AttachSourceCode(ModuleCodeImage image, object owner)
    {
        var current = new SourceExecution(image, owner, sourceExecution.Value);
        sourceExecution.Value = current;

        return new SourceExecutionScope(this, current);
    }

    internal void ReleaseSourceCode(ModuleCodeImage image)
    {
        lock (codeGate)
        {
            int count = activeCode[image];
            if (count == 1)
                activeCode.Remove(image);
            else
                activeCode[image] = count - 1;
        }
    }

    internal bool IsExecutingCode(ModuleCodeImage image)
    {
        lock (codeGate)
            return activeCode.ContainsKey(image);
    }

    internal void RestoreSourceCodeFlow(IDisposable scope) => ((SourceCodeScope)scope).RestoreFlow();

    private sealed class ExecutionFrameScope(ProcessContext context, ErlangExecutionFrame? parent) : IDisposable
    {
        public void Dispose()
        {
            context.executionFrame.Value = parent;
            Volatile.Write(ref context.visibleExecutionFrame, parent);
        }
    }

    public string? CurrentFunction => executionFrame.Value?.Function;
    public int CurrentFunctionArity => executionFrame.Value?.Arity ?? 0;

    internal Term SnapshotCurrentFunction() => ProcessInfoFrames.Current(Volatile.Read(ref visibleExecutionFrame));

    internal Term SnapshotCurrentStackTrace() => ProcessInfoFrames.Stack(Volatile.Read(ref visibleExecutionFrame), Runtime.BacktraceDepth);

    internal IReadOnlyList<ErlangExecutionFrame> SnapshotDisplayFrames()
    {
        var frames = new List<ErlangExecutionFrame>();
        ErlangExecutionFrame? frame = Volatile.Read(ref visibleExecutionFrame);
        while (frame is not null)
        {
            frames.Add(frame);
            frame = frame.Parent;
        }

        return frames;
    }

    public IDisposable EnterFunction(string module, string function, int arity)
    {
        var previous = executionFrame.Value;
        executionFrame.Value = new(
            module,
            function,
            arity,
            previous
        );
        Volatile.Write(ref visibleExecutionFrame, executionFrame.Value);

        return new ExecutionFrameScope(this, previous);
    }

    internal Term CaptureErrorStack(Term arguments, MapTerm? info, string? builtin = null)
    {
        var frames = new List<Term>();
        Term location = info is null ? Nil.Value : Term.List(Term.Tuple(Term.A(ErlangErrorMetadataNames.ErrorInfo), info));
        var frame = executionFrame.Value;
        if (builtin is not null)
            frames.Add(Term.Tuple(
                Term.A(ErlangModuleNames.Module),
                Term.A(builtin),
                arguments,
                location
            ));
        bool first = builtin is null;
        int depth = Math.Max(1, Runtime.BacktraceDepth);
        while (frame is not null && frames.Count < depth)
        {
            frames.Add(Term.Tuple(
                Term.A(frame.Module),
                Term.A(frame.Function),
                first && arguments is Cons or Nil ? arguments : Term.I(frame.Arity),
                first ? location : Nil.Value
            ));
            first = false;
            frame = frame.Parent;
        }

        return Cons.From(frames);
    }

    public ProcessRuntime Runtime
    {
        get;
    }
    public Pid Self
    {
        get;
    }
    internal RuntimeDistributionRole DistributionRole { get; set; }
    public Mailbox Mailbox { get; }
    public bool TrapExits
    {
        get; set;
    }
    public Term? ExitReason
    {
        get; internal set;
    }
    public CancellationToken Cancellation => Stop.Token;
    public Dictionary<Term, Term> Dictionary { get; } = new();

    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    public void Halt(int status) => Runtime.Halt(this, status);

    public ValueTask ReduceAsync() => ChargeAsync(1);

    internal ValueTask ChargeAsync(int count) => ChargeAsync(count, capToRemainingSlice: false);

    internal ValueTask BumpReductionsAsync(int count) => ChargeAsync(count, capToRemainingSlice: true);

    private async ValueTask ChargeAsync(int count, bool capToRemainingSlice)
    {
        Runtime.ThrowIfHalted();
        Cancellation.ThrowIfCancellationRequested();
        if (SuspensionRequested)
            await WaitIfSuspended();
        if (capToRemainingSlice)
            count = Math.Min(count, ProcessSchedulingLimits.CooperativeSlice - reductions);
        Interlocked.Add(ref cumulativeReductions, count);
        reductions += count;
        if (reductions >= ProcessSchedulingLimits.CooperativeSlice)
        {
            reductions = 0;
            Runtime.AdmitSignals(this);
            Yielding = true;
            try
            {
                await Task.Yield();
            }
            finally
            {
                Yielding = false;
            }
            Runtime.ThrowIfHalted();
            Cancellation.ThrowIfCancellationRequested();
        }
    }

    internal async ValueTask<long> WaitIfSuspended()
    {
        if (!SuspensionRequested)
            return 0;
        long start = System.Diagnostics.Stopwatch.GetTimestamp();
        while (SuspensionRequested)
        {
            Runtime.ThrowIfHalted();
            Cancellation.ThrowIfCancellationRequested();
            Runtime.AdmitSignals(this);
            Task? resumed = Runtime.Suspensions.EnterPause(this);
            if (resumed is null)
                break;
            await Mailbox.WaitForControlCompletion(resumed, Cancellation);
        }

        return System.Diagnostics.Stopwatch.GetTimestamp() - start;
    }

    public async ValueTask<T?> ReceiveAsync<T>(Func<Term, T?> select, TimeSpan? timeout = null) where T : class
    {
        Runtime.ThrowIfHalted();
        try
        {
            T? result = await Mailbox.ReceiveAsync(select, timeout, Cancellation);
            Runtime.ThrowIfHalted();

            return result;
        }
        catch (OperationCanceledException) when (Runtime.IsHaltRequested)
        {
            throw new ProcessHaltTransfer(Runtime);
        }
    }

    public void Exit(Term reason) => throw new ErlangException(reason, ErlangExceptionClasses.Exit);
}

using System.Globalization;

namespace Erlang;

internal static class ProcessIdentifierText
{
    private static ulong Channel(ProcessRuntime runtime, string node) => node == runtime.Node ? ProcessIdentifierTextParameters.LocalChannel : (ulong)AtomNameRegistry.IndexOf(node);

    public static Term PidList(ProcessRuntime runtime, Pid pid) => Term.String(string.Create(
        CultureInfo.InvariantCulture,
        $"{ProcessIdentifierTextSyntax.PidOpening}{Channel(runtime, pid.Node)}{ProcessIdentifierTextSyntax.Separator}{pid.Id & ProcessIdentifierTextParameters.StoredPidNumberMask}{ProcessIdentifierTextSyntax.Separator}{pid.Id >> ProcessIdentifierTextParameters.StoredPidSerialShift}{ProcessIdentifierTextSyntax.Closing}"
    ));

    public static Term PortList(ProcessRuntime runtime, PortTerm port) => Term.String(string.Create(
        CultureInfo.InvariantCulture,
        $"{ProcessIdentifierTextSyntax.PortOpening}{Channel(runtime, port.Node)}{ProcessIdentifierTextSyntax.Separator}{port.Id}{ProcessIdentifierTextSyntax.Closing}"
    ));

    public static Pid Pid(ProcessRuntime runtime, Term value)
    {
        var parsed = Parse(value, true);
        if (parsed.Channel != ProcessIdentifierTextParameters.LocalChannel || parsed.Number > ProcessIdentifierTextParameters.MaximumLocalPidNumber || parsed.Serial > ProcessIdentifierTextParameters.MaximumLocalPidSerial)
            throw new ErlangException(ErlangErrorReasons.BadArgument);

        return new(runtime.LocalIdentity, parsed.Number | (parsed.Serial << ProcessIdentifierTextParameters.StoredPidSerialShift));
    }

    public static PortTerm Port(ProcessRuntime runtime, Term value)
    {
        var parsed = Parse(value, false);
        if (parsed.Channel != ProcessIdentifierTextParameters.LocalChannel || parsed.Number > ProcessIdentifierTextParameters.MaximumLocalPortNumber)
            throw new ErlangException(ErlangErrorReasons.BadArgument);

        return new(runtime.LocalIdentity, parsed.Number);
    }

    private static ParsedProcessIdentifierText Parse(Term value, bool pid)
    {
        Span<byte> buffer = stackalloc byte[ProcessIdentifierTextParameters.PidMaximumInputBytes];
        int limit = pid ? ProcessIdentifierTextParameters.PidMaximumInputBytes : ProcessIdentifierTextParameters.PortMaximumInputBytes;
        int count = 0;
        Term tail = value;
        while (tail is Cons cell)
        {
            if (count == limit || cell.Head is not Integer number || number.Value < byte.MinValue || number.Value > byte.MaxValue)
                throw new ErlangException(ErlangErrorReasons.BadArgument);
            buffer[count++] = (byte)number.Value;
            tail = cell.Tail;
        }
        if (tail is not Nil)
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        ReadOnlySpan<byte> text = buffer[..count];
        int zero = text.IndexOf(ProcessIdentifierTextSyntax.NullTerminator);
        if (zero >= 0)
            text = text[..zero];
        ReadOnlySpan<byte> prefix = pid ? ProcessIdentifierTextSyntax.PidPrefix : ProcessIdentifierTextSyntax.PortPrefix;
        if (!text.StartsWith(prefix))
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        int position = prefix.Length;
        ulong channel = ReadUnsigned(text, ref position, ProcessIdentifierTextSyntax.Separator);
        ulong id = ReadUnsigned(text, ref position, pid ? ProcessIdentifierTextSyntax.Separator : ProcessIdentifierTextSyntax.Closing);
        ulong serial = pid ? ReadUnsigned(text, ref position, ProcessIdentifierTextSyntax.Closing) : 0;
        if (position != text.Length)
            throw new ErlangException(ErlangErrorReasons.BadArgument);

        return new(pid ? channel : (uint)channel, id, serial);
    }

    private static ulong ReadUnsigned(ReadOnlySpan<byte> text, ref int position, char delimiter)
    {
        int first = position;
        ulong value = 0;
        while (position < text.Length && text[position] is >= ProcessIdentifierTextSyntax.LowestDigit and <= ProcessIdentifierTextSyntax.HighestDigit)
        {
            value = unchecked(value * ProcessIdentifierTextParameters.DecimalRadix + (ulong)(text[position] - ProcessIdentifierTextSyntax.LowestDigit));
            position++;
        }
        if (position == first || position == text.Length || text[position++] != delimiter)
            throw new ErlangException(ErlangErrorReasons.BadArgument);

        return value;
    }
}

