public sealed partial class ProcessRuntime
{
    public EtfDecodedTerm ImportExternalTerm(ReadOnlySpan<byte> data, EtfDecodeOptions? options = null, int maxBytes = ExternalTermFormat.DefaultMaxBytes)
    {
        options ??= new();
        if (options.PidFactory is not null || options.PortFactory is not null || options.ReferenceFactory is not null)
            throw new ArgumentException(RuntimeExternalTermDiagnostics.ResourceFactory, nameof(options));
        EtfDecodeOptions prepared = options with
        {
            LocalSeed = LocalTermSeed,
            ExternalFunctionFactory = options.ExternalFunctionFactory ?? ((identity, safe) => Functions.External(this, identity, safe)),
            LocalFunctionFactory = options.LocalFunctionFactory ?? ((code, arity, environment) => Functions.Restore(
                this,
                new LocalFunctionIdentity(
                    code.Module,
                    null,
                    code.Index,
                    code.OldUnique,
                    code.Unique,
                    code.OldIndex
                ),
                arity,
                environment
            ))
        };
        EtfDecodeOptions decoding = prepared with { NodeAdmission = epochs => AdmitExternalDecode(prepared, epochs) };

        return ExternalTermFormat.DecodeOne(data, decoding, maxBytes);
    }

    internal EtfDecodeAdmission AdmitExternalDecode(EtfDecodeOptions options, IReadOnlyList<EtfNodeEpoch> epochs)
    {
        LocalNodeSnapshot snapshot;
        IDisposable reservation;
        lock (gate)
        {
            ObjectDisposedException.ThrowIf(disposed, this);
            ThrowIfHalted();
            snapshot = LocalIdentity.Snapshot;
            reservation = KnownNodes.ReserveEpochs(epochs, snapshot);
        }
        try
        {
            EtfDecodeOptions captured = options with
            {
                LocalNode = snapshot.Node,
                LocalCreation = snapshot.Creation,
                NodeIdentity = LocalIdentity,
                NodeAdmission = null,
                PidFactory = value => ObserveDecodedIdentifier(RehydratePid(value, snapshot)),
                PortFactory = value => ObserveDecodedIdentifier(RehydratePort(value, snapshot)),
                ReferenceFactory = value => ObserveDecodedIdentifier(ReferenceResources.Rehydrate(value, snapshot))
            };

            return new(captured, reservation, ObserveImportedGraph);
        }
        catch
        {
            reservation.Dispose();
            throw;
        }
    }

    private void ObserveImportedGraph(Term term)
    {
        RequireExternalTermDomain(term);
        KnownNodes.Observe(term);
    }

    private T ObserveDecodedIdentifier<T>(T value) where T : Term
    {
        KnownNodes.Observe(value);

        return value;
    }
}

namespace Erlang;

public sealed partial class ProcessRuntime
{
    public RuntimeExternalTermReservation ReserveExternalTerm(Term term)
    {
        ArgumentNullException.ThrowIfNull(term);
        lock (gate)
        {
            ObjectDisposedException.ThrowIf(disposed || IsHaltRequested, nameof(ProcessRuntime));
            RequireExternalTermDomain(term);
            KnownNodes.Observe(term);

            return new(term);
        }
    }

    internal void ObserveIncomingTerm(Term term)
    {
        if (term is Pid or ReferenceTerm or PortTerm or Cons or TupleTerm or MapTerm or NativeRecordTerm ||
            term is FunctionTerm { Environment.Count: > 0 })
            KnownNodes.Observe(term);
    }

    private void RequireExternalTermDomain(Term root)
    {
        var pending = new Stack<Term>();
        var visited = new HashSet<Term>(ReferenceEqualityComparer.Instance);
        pending.Push(root);
        while (pending.TryPop(out var term))
        {
            if (!visited.Add(term))
                continue;
            LocalNodeIdentity? owner = term switch
            {
                Pid pid => pid.LocalIdentity,
                ReferenceTerm reference => reference.LocalIdentity,
                PortTerm port => port.LocalIdentity,
                _ => null
            };
            if (owner is not null && !ReferenceEquals(owner, LocalIdentity))
                throw new ArgumentException(RuntimeExternalTermDiagnostics.ForeignIdentity, nameof(root));
            switch (term)
            {
                case Cons list:
                    pending.Push(list.Head);
                    pending.Push(list.Tail);
                    break;
                case TupleTerm tuple:
                    foreach (Term item in tuple.Items)
                        pending.Push(item);
                    break;
                case MapTerm map:
                    foreach (var entry in map.Entries)
                    {
                        pending.Push(entry.Key);
                        pending.Push(entry.Value);
                    }
                    break;
                case NativeRecordTerm record:
                    foreach (Term item in record.Values)
                        pending.Push(item);
                    break;
                case FunctionTerm function:
                    foreach (Term item in function.Environment)
                        pending.Push(item);
                    break;
            }
        }
    }
}

namespace Erlang;

public sealed partial class ProcessRuntime
{
    private ProcessContext? localNodeKernel;
    private RuntimeLocalNodeEvents? localNodeEvents;

    public bool IsDistributionAlive
    {
        get
        {
            lock (gate)
                return localNodeKernel is { } kernel && kernel.DistributionRole == RuntimeDistributionRole.Kernel && IsOwnedLiveNodeProcess(kernel);
        }
    }

    public RuntimeLocalNodeEvents LocalNodeEvents
    {
        get
        {
            lock (gate)
            {
                ObjectDisposedException.ThrowIf(disposed, RuntimeLocalNodeAdmissionNames.Closed);

                return localNodeEvents ??= new(this, gate);
            }
        }
    }

    internal bool IsOwnedLiveNodeProcess(ProcessContext process)
    {
        return ReferenceEquals(process.Runtime, this) && !disposed && !IsHaltRequested && !process.Terminated &&
            !process.Stop.IsCancellationRequested && !process.Done.Task.IsCompleted &&
            processes.TryGetValue(process.Self, out var owned) && ReferenceEquals(owned, process);
    }

    internal bool IsCurrentLocal(Pid pid)
    {
        var current = LocalIdentity.Snapshot;
        var target = pid.WireIdentity;

        return pid.LocalIdentity is not null ? ReferenceEquals(pid.LocalIdentity, LocalIdentity) : target.Node == current.Node && target.Creation == current.Creation;
    }

    internal bool IsCurrentLocal(ReferenceTerm reference)
    {
        var current = LocalIdentity.Snapshot;
        var target = reference.WireIdentity;

        return reference.LocalIdentity is not null ? ReferenceEquals(reference.LocalIdentity, LocalIdentity) : target.Node == current.Node && target.Creation == current.Creation;
    }

    internal Term AdmitObservedLocalNode(ProcessContext caller, Term name, Term creation)
    {
        if (name is not Atom node || !DistributionNodeIdentity.IsValid(node) || node.Name == ProcessNodeDefaults.Local ||
            !RuntimeNodeCreation.TryConvert(creation, out uint requestedCreation) ||
            !Modules.HasExport(ErlangModuleNames.Module, RuntimeNodeControlNames.MonitorTrap, RuntimeLocalNodeAdmissionNames.MonitorTrapArity))
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        lock (gate)
        {
            if (!IsOwnedLiveNodeProcess(caller) || localNodeKernel is not null ||
                !names.TryGetValue(RuntimeNodeControlNames.Kernel, out var registered) || registered is not Pid kernelPid || !IsCurrentLocal(kernelPid) ||
                !processes.TryGetValue(kernelPid, out var kernel) || !IsOwnedLiveNodeProcess(kernel) || kernel.DistributionRole != RuntimeDistributionRole.None)
                throw new ErlangException(ErlangErrorReasons.BadArgument);
            uint selected = SelectObservedExternalEpochCreation(node.Name, requestedCreation);
            kernel.DistributionRole = RuntimeDistributionRole.Kernel;
            localNodeKernel = kernel;
            LocalIdentity.Publish(node.Name, selected);
            localNodeEvents?.Notify(RuntimeLocalNodeAdmissionNames.NodeUp, node);

            return Term.A(ErlangBooleanAtoms.True);
        }
    }

    private void LocalNodeProcessTerminated(ProcessContext process, Term reason)
    {
        localNodeEvents?.ProcessTerminated(process);
        if (ReferenceEquals(localNodeKernel, process))
            StopLocalNode(reason);
    }

    private void StopLocalNode()
    {
        StopLocalNode(Term.A(RuntimeNodeMonitorNames.KernelTerminated));
    }

    private void StopLocalNode(Term reason)
    {
        if (localNodeKernel is null)
            return;
        Atom previous = NodeAtom;
        localNodeKernel.DistributionRole = RuntimeDistributionRole.None;
        localNodeKernel = null;
        distributionPending?.LocalKernelStopped(reason);
        LocalIdentity.Publish(ProcessNodeDefaults.Local, 0);
        localNodeEvents?.NotifyLocalDown(previous, reason);
    }
}

