internal sealed partial class RuntimeKnownNodes
{
    private readonly Dictionary<(string Node, uint Creation), int> reservedEpochs = new();

    internal IDisposable ReserveEpochs(IReadOnlyList<EtfNodeEpoch> epochs, LocalNodeSnapshot snapshot)
    {
        var keys = epochs.Where(epoch => !epoch.LocalMarker &&
            (epoch.Node != snapshot.Node || epoch.Creation != snapshot.Creation))
            .Select(epoch => (epoch.Node, epoch.Creation)).Distinct().ToArray();
        var reservation = new RuntimeExternalEpochReservation(() => ReleaseEpochs(keys));
        lock (gate)
        {
            foreach (var key in keys)
                _ = checked(reservedEpochs.GetValueOrDefault(key) + 1);
            foreach (var key in keys)
                reservedEpochs[key] = reservedEpochs.GetValueOrDefault(key) + 1;
        }

        return reservation;
    }

    private void ReleaseEpochs((string Node, uint Creation)[] keys)
    {
        lock (gate)
            foreach (var key in keys)
            {
                int count = reservedEpochs[key];
                if (count == 1)
                    reservedEpochs.Remove(key);
                else
                    reservedEpochs[key] = count - 1;
            }
    }
}

using System.Runtime.CompilerServices;

namespace Erlang;

internal sealed partial class RuntimeKnownNodes(LocalNodeIdentity localIdentity)
{
    private readonly object gate = new();
    private readonly Dictionary<string, List<WeakReference<Term>>> nodes = new(StringComparer.Ordinal);
    private readonly ConditionalWeakTable<Term, object> observed = new();

    public void Observe(Term term)
    {
        var pending = new Stack<Term>();
        var visited = new HashSet<Term>(ReferenceEqualityComparer.Instance);
        pending.Push(term);
        lock (gate)
            while (pending.TryPop(out var value))
            {
                if (!visited.Add(value))
                    continue;
                string? name = value switch
                {
                    Pid pid => pid.Node,
                    PortTerm port => port.Node,
                    ReferenceTerm reference => reference.Node,
                    _ => null
                };
                bool local = value switch
                {
                    Pid pid => ReferenceEquals(pid.LocalIdentity, localIdentity),
                    PortTerm port => ReferenceEquals(port.LocalIdentity, localIdentity),
                    ReferenceTerm reference => ReferenceEquals(reference.LocalIdentity, localIdentity),
                    _ => false
                };
                if (name is not null && !local && !observed.TryGetValue(value, out _))
                {
                    observed.Add(value, new object());
                    if (!nodes.TryGetValue(name, out var references))
                        nodes.Add(name, references = new());
                    references.Add(new(value));
                }
                switch (value)
                {
                    case Cons list:
                        pending.Push(list.Head);
                        pending.Push(list.Tail);
                        break;
                    case NativeRecordTerm record:
                        foreach (Term item in record.Values)
                            pending.Push(item);
                        break;
                    case TupleTerm tuple:
                        foreach (Term item in tuple.Items)
                            pending.Push(item);
                        break;
                    case MapTerm map:
                        foreach (var pair in map.Entries)
                        {
                            pending.Push(pair.Key);
                            pending.Push(pair.Value);
                        }
                        break;
                    case FunctionTerm function:
                        foreach (Term item in function.Environment)
                            pending.Push(item);
                        break;
                }
            }
    }

    internal bool HasRetainedExternalEpoch(string name, uint creation)
    {
        lock (gate)
        {
            if (reservedEpochs.ContainsKey((name, creation)))
                return true;
            if (!nodes.TryGetValue(name, out var references))
                return false;

            return references.Any(reference => reference.TryGetTarget(out var term) && (term switch
            {
                Pid pid => pid.LocalIdentity is null && pid.Creation == creation,
                PortTerm port => port.LocalIdentity is null && port.Creation == creation,
                ReferenceTerm value => value.LocalIdentity is null && value.Creation == creation,
                _ => false
            }));
        }
    }

    public IReadOnlyList<string> Snapshot()
    {
        lock (gate)
        {
            foreach (var pair in nodes.ToArray())
            {
                pair.Value.RemoveAll(reference => !reference.TryGetTarget(out _));
                if (pair.Value.Count == 0)
                    nodes.Remove(pair.Key);
            }

            return nodes.Keys.Where(name => name != localIdentity.Snapshot.Node).Order(StringComparer.Ordinal).ToArray();
        }
    }
}

using System.Numerics;

namespace Erlang;

public sealed class RuntimeLocalNodeEvents
{
    private readonly ProcessRuntime runtime;
    private readonly object gate;
    private readonly Dictionary<ProcessContext, Dictionary<RuntimeNodeMonitorOptions, BigInteger>> subscribers = new(ReferenceEqualityComparer.Instance);
    private bool closed;

    internal RuntimeLocalNodeEvents(ProcessRuntime runtime, object gate)
    {
        this.runtime = runtime;
        this.gate = gate;
    }

    public int Monitor(ProcessContext process, bool enable) => checked((int)Monitor(process, enable, RuntimeNodeMonitorOptions.Empty));

    internal BigInteger Monitor(ProcessContext process, bool enable, RuntimeNodeMonitorOptions options)
    {
        ArgumentNullException.ThrowIfNull(process);
        lock (gate)
        {
            ObjectDisposedException.ThrowIf(closed || runtime.IsHaltRequested, RuntimeLocalNodeAdmissionNames.Closed);
            if (!runtime.IsOwnedLiveNodeProcess(process))
                throw new ArgumentException(RuntimeLocalNodeAdmissionNames.Owner, nameof(process));
            if (!subscribers.TryGetValue(process, out var registrations))
            {
                if (!enable)
                    return BigInteger.Zero;
                registrations = new();
                subscribers.Add(process, registrations);
            }
            BigInteger previous = registrations.GetValueOrDefault(options);
            if (enable)
                registrations[options] = previous + BigInteger.One;
            else
            {
                registrations.Remove(options);
                if (registrations.Count == 0)
                    subscribers.Remove(process);
            }

            return previous;
        }
    }

    internal void Notify(string eventName, Atom node)
    {
        Notify(
            eventName,
            node,
            RuntimeNodeMonitorType.Visible,
            null,
            Term.A(RuntimeNodeMonitorNames.KernelTerminated)
        );
    }

    internal void NotifyLocalDown(Atom node, Term reason)
    {
        Term normalized = reason is Atom { Name: RuntimeNodeMonitorNames.NoNetwork } ? reason : Term.A(RuntimeNodeMonitorNames.KernelTerminated);
        Notify(
            RuntimeLocalNodeAdmissionNames.NodeDown,
            node,
            RuntimeNodeMonitorType.Visible,
            null,
            normalized
        );
    }

    internal void NotifyRemote(
        string eventName,
        Atom node,
        RuntimeNodeMonitorType nodeType,
        uint connectionId,
        Term? downReason = null
    )
    {
        if (eventName is not RuntimeLocalNodeAdmissionNames.NodeUp and not RuntimeLocalNodeAdmissionNames.NodeDown)
            throw new ArgumentOutOfRangeException(nameof(eventName));
        if (nodeType is not RuntimeNodeMonitorType.Visible and not RuntimeNodeMonitorType.Hidden)
            throw new ArgumentOutOfRangeException(nameof(nodeType));
        if (eventName == RuntimeLocalNodeAdmissionNames.NodeDown && downReason is null)
            throw new ArgumentNullException(nameof(downReason));
        Notify(
            eventName,
            node,
            nodeType,
            connectionId,
            downReason
        );
    }

    private void Notify(
        string eventName,
        Atom node,
        RuntimeNodeMonitorType nodeType,
        uint? connectionId,
        Term? downReason
    )
    {
        lock (gate)
        {
            foreach (var subscriber in subscribers.ToArray())
            {
                if (!runtime.IsOwnedLiveNodeProcess(subscriber.Key))
                    continue;
                foreach (var registration in subscriber.Value.ToArray())
                {
                    if (registration.Key.Type == RuntimeNodeMonitorType.Hidden && nodeType != RuntimeNodeMonitorType.Hidden ||
                        registration.Key.Type is RuntimeNodeMonitorType.Default or RuntimeNodeMonitorType.Visible && nodeType != RuntimeNodeMonitorType.Visible)
                        continue;
                    Term message = Message(
                        eventName,
                        node,
                        registration.Key,
                        nodeType,
                        connectionId,
                        downReason
                    );
                    for (BigInteger index = BigInteger.Zero; index < registration.Value; index++)
                        runtime.SendSystem(subscriber.Key.Self, message);
                }
            }
        }
    }

    private static Term Message(
        string eventName,
        Atom node,
        RuntimeNodeMonitorOptions options,
        RuntimeNodeMonitorType nodeType,
        uint? connectionId,
        Term? downReason
    )
    {
        if (!options.IncludeInfo)
            return Term.Tuple(Term.A(eventName), node);
        var entries = new List<KeyValuePair<Term, Term>>();
        if (options.ConnectionId)
            entries.Add(new(Term.A(RuntimeNodeMonitorNames.ConnectionId), connectionId is uint id ? Term.I(id) : Term.A(RuntimeNodeMonitorNames.Undefined)));
        if (options.DownReason && eventName == RuntimeLocalNodeAdmissionNames.NodeDown)
            entries.Add(new(Term.A(RuntimeNodeMonitorNames.DownReason), downReason!));
        if (options.Type != RuntimeNodeMonitorType.Default)
            entries.Add(new(
                Term.A(RuntimeNodeMonitorNames.NodeType),
                Term.A(nodeType == RuntimeNodeMonitorType.Visible ? RuntimeNodeMonitorNames.Visible : RuntimeNodeMonitorNames.Hidden)
            ));
        Term info = options.InfoMap ? new MapTerm(entries) : Cons.From(entries.Select(entry => Term.Tuple(entry.Key, entry.Value)));

        return Term.Tuple(Term.A(eventName), node, info);
    }

    internal void ProcessTerminated(ProcessContext process)
    {
        lock (gate)
            subscribers.Remove(process);
    }

    internal void Close()
    {
        lock (gate)
        {
            closed = true;
            subscribers.Clear();
        }
    }
}

