        await outsider.Invoke(context => Reject(() => pending.EnqueueConnectedOutput(handle, context, outgoingLocalFunction)));
        await input.Invoke(context =>
        {
            pending.EnqueueConnectedOutput(handle, context, outgoingLocalFunction);

            return true;
        });
