        });
        await adoptionStarted.Task.WaitAsync(ConnectedDistributionHostNames.Deadline);
        await controller.InvokeAsync(async context =>
        {
            Check(await context.ReceiveAsync<Term>(_ => null, TimeSpan.Zero) is null);

            return true;
        });
