            Check(DistributionControllerAdapters.GetOption(context, opaque, Term.A(DistributionControllerNames.GetSize)).Equals(Term.A(ErlangBooleanAtoms.False)));
            Check(DistributionControllerAdapters.SetOption(
                context,
                opaque,
